BEGIN IMMEDIATE;

-- v0.35 adds four series in the existing story_series tables: the Kojiki
-- (Chamberlain; a new long Izanagi/Izanami version, the existing rock-cave
-- story and three new parts), the Kalevala (Crawford, four parts), the
-- Mahabharata (Ganguli: Nala, Savitri, Kurukshetra) and the Shahnameh
-- (Zimmern's prose retelling, three parts), plus a standalone reading of
-- thirteen tales from the Soushen ji. Every section keeps its own anchor
-- claim with evidence at the same locator; skipped sections are named, not
-- filled in. Finnish and New Persian are registered as languages.

INSERT OR IGNORE INTO sources(
    id,title,original_title,source_type,evidence_tier,institution,author_or_editor,language_id,publication_date,accessed_date,url,stable_url,catalogue_number,rights_status,source_perspective,community_or_lineage,collector_context,living_tradition,access_or_reuse_restrictions,community_permission_required,translation_status,verification_status,notes
) VALUES
('source.finnish.kalevala_crawford.gutenberg','Kalevala: The Epic Poem of Finland, tr. John Martin Crawford (1888)','Kalevala (Elias Lönnrot, 1849 edition)','HISTORICAL_TRANSLATION',3,'Project Gutenberg (eBook #5186; volumes #5184–#5185)','Elias Lönnrot (compiler); translated by John Martin Crawford','lang.en','1888','2026-10-24','https://www.gutenberg.org/ebooks/5186',NULL,'Fifty runes in two volumes','Public-domain translation distributed by Project Gutenberg','English verse translation of Lönnrot''s 1849 Kalevala, a nineteenth-century compilation of Finnish and Karelian oral poetry',NULL,'Public web page',0,'Cite rune numbers; publish independent retellings rather than the translation.',0,'English translation of the Finnish','URL_SYNTAX_VALID','Project Gutenberg eBook #5186 (complete; volumes #5184 and #5185), matched through public search-index metadata on 2026-10-24.'),
('source.indian.mahabharata_ganguli.sacredtexts','The Mahabharata of Krishna-Dwaipayana Vyasa, tr. Kisari Mohan Ganguli (1883–1896)','Mahābhārata','HISTORICAL_TRANSLATION',3,'Internet Sacred Text Archive (also Project Gutenberg, e.g. eBook #11894 for Vana Parva Part 1)','Attributed to Vyāsa; translated by Kisari Mohan Ganguli','lang.en','1883–1896','2026-10-24','https://sacred-texts.com/hin/maha/index.htm',NULL,'Eighteen books (parvas) divided into sub-parvas and numbered sections','Public-domain translation','Complete nineteenth-century English prose translation of the Sanskrit epic, following the vulgate (Bengal and Bombay) text rather than the later Poona critical edition',NULL,'Public web page',0,'Cite book, sub-parva and section; section numbers differ from the critical edition; publish independent retellings rather than the translation.',0,'English translation of the Sanskrit','URL_SYNTAX_VALID','Sacred-texts and Project Gutenberg editions of Ganguli''s translation, matched through public search-index metadata on 2026-10-24.'),
('source.persian.epic_of_kings_zimmern','The Epic of Kings: Stories Retold from Firdusi, by Helen Zimmern (1883)','Shahnameh (Ferdowsi, c. 1010 CE)','HISTORICAL_PROSE_RETELLING',4,'MIT Internet Classics Archive (also HathiTrust, from the 1883 Henry Holt edition)','Ferdowsi (original); retold in English prose by Helen Zimmern','lang.en','1883','2026-10-24','https://classics.mit.edu/Ferdowsi/kings.html',NULL,'Eighteen sections from The Shahs of Old to The Death of Rustem','Public-domain retelling','Abridged English prose retelling of selected stories from Ferdowsi''s Shahnameh, a medieval Persian epic of the kings and heroes of Iran; it shortens and rephrases the poem and is not a full translation',NULL,'Public web page',0,'Cite Zimmern''s section titles; treat the wording as a nineteenth-century retelling, not as Ferdowsi''s text; publish independent retellings.',0,'English prose retelling of the Persian verse','URL_SYNTAX_VALID','Zimmern''s retelling as hosted by the MIT Internet Classics Archive and catalogued by HathiTrust (Henry Holt, 1883), matched through public search-index metadata on 2026-10-24.'),
('source.china.soushenji.gutenberg','搜神記 (Soushen ji), compiled by Gan Bao (Project Gutenberg edition)','搜神記','PRIMARY_TEXT_DIGITAL_EDITION',4,'Project Gutenberg (eBook #25362; volumes also as #7260 and #7270)','干寶 Gan Bao (fl. 317–322)','lang.lzh','4th century CE (twenty-juan received text)','2026-10-24','https://www.gutenberg.org/ebooks/25362',NULL,'Twenty juan of anomaly accounts in the received text','Classical Chinese text in the public domain','Received twenty-juan text of Gan Bao''s fourth-century collection of anomaly accounts (zhiguai), reconstructed from later quotations; the received arrangement is not Gan Bao''s original',NULL,'Public web page',0,'Cite juan and tale; publish independent vernacular retellings.',0,NULL,'URL_SYNTAX_VALID','Project Gutenberg eBook #25362 (complete) with volumes #7260 and #7270, matched through public search-index metadata on 2026-10-24.');

