('lang.fin','Finnish','芬兰语','fin','Latin','Modern Finnish (19th-century literary)','Language of Lönnrot''s Kalevala (1835; expanded edition 1849), compiled from Finnish and Karelian oral poetry.'),
('lang.fas','Persian','波斯语','fas','Perso-Arabic','New Persian (Early)','Language of Ferdowsi''s Shahnameh (completed c. 1010 CE), written in New Persian in the Perso-Arabic script.');

INSERT OR IGNORE INTO entities(
    id,canonical_name,name_zh,original_name,transliteration,primary_type,primary_civilization_id,historical_period,description,research_status,evidence_status,record_version,metadata_json,created_at,updated_at
) VALUES
('deity.japanese.takamimusubi','Takami-musubi','高御产巢日神','高御產巢日神','Takami-musubi-no-kami','DEITY','civ.japanese_shinto','Kojiki (712 CE)','One of the three deities who came into being first in the Plain of High Heaven; also called Takagi-no-kami, he directs the pacification of the Central Land and the descent of Ninigi (Kojiki, Sect. I, XXX–XXXIII).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('deity.japanese.kamimusubi','Kami-musubi','神产巢日神','神產巢日神','Kami-musubi-no-kami','DEITY','civ.japanese_shinto','Kojiki (712 CE)','One of the three deities who came into being first; she restores Ōkuninushi to life and names Sukuna-bikona as her child (Kojiki, Sect. I, XXII, XXVII).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('deity.japanese.okuninushi','Ōkuninushi','大国主神','大國主神','Ōkuninushi-no-kami','DEITY','civ.japanese_shinto','Kojiki (712 CE)','Descendant of Susanoo in the Kojiki, also called Ōnamuji, Ashihara-shiko-wo, Yachihoko and Utsushi-kunitama; he heals the hare of Inaba, survives his brothers'' plots and Susanoo''s trials, makes the land with Sukuna-bikona and yields it to the heavenly line (Kojiki, Sect. XX–XXXII).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('deity.japanese.suseribime','Suseri-bime','须势理毘卖','須勢理毘賣','Suseri-bime-no-mikoto','DEITY','civ.japanese_shinto','Kojiki (712 CE)','Daughter of Susanoo in the Nether-Distant-Land who marries Ōkuninushi, saves him from her father''s trials with magic scarves and flees with him to become his chief wife (Kojiki, Sect. XXIII, XXV).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('creature.japanese.hare_of_inaba','White Hare of Inaba','稻羽之素兔','稻羽之素菟','Inaba no shiro-usagi','DIVINE_BEAST','civ.japanese_shinto','Kojiki (712 CE)','Hare skinned by the sea-creatures it tricked, made worse by the eighty deities and healed by Ōkuninushi with fresh water and sedge pollen; the Kojiki says it is now called the Hare Deity (Sect. XXI).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('deity.japanese.sukunabikona','Sukuna-bikona','少名毘古那神','少名毘古那神','Sukuna-bikona-no-kami','DEITY','civ.japanese_shinto','Kojiki (712 CE)','Tiny deity who arrives over the waves in a seed-pod boat; Kami-musubi names him her child who slipped through her fingers, and he makes the land with Ōkuninushi before crossing to the Eternal Land (Kojiki, Sect. XXVII).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('deity.japanese.kotoshironushi','Kotoshironushi','事代主神','事代主神','Yae-kotoshironushi-no-kami','DEITY','civ.japanese_shinto','Kojiki (712 CE)','Son of Ōkuninushi who, fetched from fishing at Cape Miho, agrees to yield the land, overturns his boat and hides behind a green fence (Kojiki, Sect. XXXII).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('deity.japanese.takeminakata','Takeminakata','建御名方神','建御名方神','Takeminakata-no-kami','DEITY','civ.japanese_shinto','Kojiki (712 CE)','Son of Ōkuninushi who challenges Takemikazuchi to a trial of strength, is overpowered and flees to the sea of Suwa in Shinano, promising never to leave it (Kojiki, Sect. XXXII).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('deity.japanese.ame_no_wakahiko','Ame-no-Wakahiko','天若日子','天若日子','Ame-no-Wakahiko','DEITY','civ.japanese_shinto','Kojiki (712 CE)','Heavenly envoy who marries Ōkuninushi''s daughter and sends no report for eight years; he shoots the pheasant messenger and is killed by his own arrow thrown back from heaven (Kojiki, Sect. XXXI).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('place.japanese.ne_no_katasu_kuni','Ne-no-katasu-kuni','根之坚洲国','根之堅州國','Ne-no-katasu-kuni','REALM','civ.japanese_shinto','Kojiki (712 CE)','The Nether-Distant-Land where Susanoo dwells, reached through a fork in a tree; Ōkuninushi undergoes Susanoo''s trials there and escapes over the Even Pass of Yomi (Kojiki, Sect. XII, XXIII).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('deity.japanese.ninigi','Ninigi','迩迩艺命','邇邇藝命','Hiko-ho-no-ninigi-no-mikoto','DEITY','civ.japanese_shinto','Kojiki (712 CE)','Grandson of Amaterasu sent down from High Heaven to rule the Central Land; he descends on Takachiho in Himuka, marries Konohana-sakuya-hime and rejects her sister Iwanaga-hime (Kojiki, Sect. XXXIII–XXXVIII).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('deity.japanese.sarutahiko','Sarutahiko','猿田毘古神','猿田毘古神','Sarutahiko-no-kami','DEITY','civ.japanese_shinto','Kojiki (712 CE)','Earthly deity who shines at the heavenly crossroads and offers to guide Ninigi''s descent; Ame-no-Uzume escorts him home, and he drowns fishing at Azaka (Kojiki, Sect. XXXIII, XXXV–XXXVI).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('deity.japanese.oyamatsumi','Ōyamatsumi','大山津见神','大山津見神','Ōyamatsumi-no-kami','DEITY','civ.japanese_shinto','Kojiki (712 CE)','Great mountain deity born of Izanagi and Izanami; father of Konohana-sakuya-hime and Iwanaga-hime, whose return brings the curse of brief life on the heavenly line (Kojiki, Sect. VI, XXXVII).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('deity.japanese.konohana_sakuya_hime','Konohana-sakuya-hime','木花之佐久夜毘卖','木花之佐久夜毘賣','Konohana-no-sakuya-bime','DEITY','civ.japanese_shinto','Kojiki (712 CE)','Daughter of Ōyamatsumi, also called Kamu-ata-tsu-hime, who marries Ninigi and, doubted by him, gives birth inside a burning doorless hall to Hoderi, Hosuseri and Hoori (Kojiki, Sect. XXXVII–XXXVIII).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('deity.japanese.iwanaga_hime','Iwanaga-hime','石长比卖','石長比賣','Iwanaga-hime','DEITY','civ.japanese_shinto','Kojiki (712 CE)','Elder daughter of Ōyamatsumi, sent with her sister to Ninigi and returned for her ugliness; her rejection leaves the heavenly line with lives as brief as blossoms (Kojiki, Sect. XXXVII).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('deity.japanese.hoori','Hoori','火远理命','火遠理命','Hoori-no-mikoto','DEITY','civ.japanese_shinto','Kojiki (712 CE)','Youngest son of Ninigi and Konohana-sakuya-hime, Yamasachi-hiko, who loses his brother''s fish-hook, recovers it in the sea deity''s palace, marries Toyotama-bime and subdues his brother with the tide jewels (Kojiki, Sect. XXXVIII–XLII).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('deity.japanese.hoderi','Hoderi','火照命','火照命','Hoderi-no-mikoto','DEITY','civ.japanese_shinto','Kojiki (712 CE)','Eldest son of Ninigi, Umisachi-hiko, who demands back the fish-hook his brother lost and, subdued by the tide jewels, becomes his guard; named as ancestor of the Hayato of Ata (Kojiki, Sect. XXXVIII–XLI).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('deity.japanese.watatsumi','Watatsumi','绵津见神','綿津見神','Wata-tsu-mi-no-kami','DEITY','civ.japanese_shinto','Kojiki (712 CE)','The sea deity in whose fish-scale palace Hoori stays three years; he finds the lost hook in a sea-bream''s throat and gives Hoori the tide-flowing and tide-ebbing jewels (Kojiki, Sect. XL).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('deity.japanese.toyotama_hime','Toyotama-bime','丰玉毘卖','豐玉毘賣','Toyotama-bime-no-mikoto','DEITY','civ.japanese_shinto','Kojiki (712 CE)','Daughter of the sea deity who marries Hoori, gives birth on the shore in a hut thatched with cormorant feathers and, seen in her true form as a great wani, returns to the sea (Kojiki, Sect. XL, XLII).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('artifact.japanese.tide_jewels','Tide-flowing and tide-ebbing jewels','潮盈珠与潮干珠','鹽盈珠・鹽乾珠','Shiomitsu-tama and Shiohiru-tama','SACRED_OBJECT','civ.japanese_shinto','Kojiki (712 CE)','Pair of jewels given by the sea deity to Hoori: one makes the tide flow in to drown his brother, the other makes it ebb to save him (Kojiki, Sect. XL–XLI).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('place.japanese.watatsumi_palace','Palace of Watatsumi','绵津见神宫','綿津見神宮','Wata-tsu-mi-no-kami-no-miya','MYTHICAL_PLACE','civ.japanese_shinto','Kojiki (712 CE)','The sea deity''s palace, built like the scales of fishes, reached by following a current in a closely woven bamboo boat; a cassia tree stands by its well (Kojiki, Sect. XL).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('person.japanese.keiko','Keikō','景行天皇','大帶日子淤斯呂和氣天皇','Ōtarashi-hiko-oshiro-wake','PERSON','civ.japanese_shinto','Kojiki (712 CE)','Twelfth sovereign in the Kojiki''s sequence, ruling from the palace of Hishiro at Makimuku, who sends his fierce son Yamato Takeru first west and then east (Kojiki, Sect. LXXVI–XC).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.japanese.yamato_hime','Yamato-hime','倭比卖命','倭比賣命','Yamato-hime-no-mikoto','HERO','civ.japanese_shinto','Kojiki (712 CE)','Aunt of Yamato Takeru serving at the shrine of Ise, who lends him her robes for the Kumaso deed and gives him the Kusanagi sword and a bag holding a fire-striker (Kojiki, Sect. LXXX, LXXXII).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('person.japanese.kumaso_takeru','Kumaso Takeru','熊曾建','熊曾建','Kumaso Takeru','PERSON','civ.japanese_shinto','Kojiki (712 CE)','Two brothers, the bravoes of Kumaso in the west, killed at their housewarming feast by Yamato Takeru disguised as a girl; the younger gives him the name Yamato Takeru as he dies (Kojiki, Sect. LXXX).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('person.japanese.izumo_takeru','Izumo Takeru','出云建','出雲建','Izumo Takeru','PERSON','civ.japanese_shinto','Kojiki (712 CE)','Bravo of Izumo whom Yamato Takeru befriends, tricks into exchanging his sword for a wooden one while bathing in the Hi river, and kills (Kojiki, Sect. LXXXI).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.japanese.oto_tachibana_hime','Oto-tachibana-hime','弟橘比卖','弟橘比賣命','Oto-tachibana-hime-no-mikoto','HERO','civ.japanese_shinto','Kojiki (712 CE)','Consort of Yamato Takeru who enters the sea at the Hashirimizu crossing to calm the waves sent by the deity of the strait; her comb washes ashore seven days later (Kojiki, Sect. LXXXIV).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.japanese.miyazu_hime','Miyazu-hime','美夜受比卖','美夜受比賣','Miyazu-hime','HERO','civ.japanese_shinto','Kojiki (712 CE)','Woman of Owari whom Yamato Takeru promises to marry on his way east and weds on his return; he leaves the Kusanagi sword with her before going to Mount Ibuki (Kojiki, Sect. LXXXIII, LXXXVII).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('deity.japanese.ibuki_deity','Deity of Mount Ibuki','伊服岐能山之神','伊服岐能山之神','Ibuki-no-yama-no-kami','DEITY','civ.japanese_shinto','Kojiki (712 CE)','Deity of Mount Ibuki who appears to the swordless Yamato Takeru as a white boar the size of an ox and, mistaken for its messenger, strikes him with a great hailstorm (Kojiki, Sect. LXXXVIII).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('text.finnish.kalevala','Kalevala','卡勒瓦拉','Kalevala','Kalevala','TEXT','civ.finnish','Kalevala (Lönnrot 1849, from oral poetry)','Finnish national epic compiled by Elias Lönnrot from Finnish and Karelian oral runes (1835; expanded fifty-rune edition 1849).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('deity.finnish.ilmatar','Ilmatar','伊尔玛塔尔（大气之女）','Ilmatar','Ilmatar','DEITY','civ.finnish','Kalevala (Lönnrot 1849, from oral poetry)','Daughter of the air who descends to the sea and floats for ages as the Water-mother; from the broken eggs of a duck nesting on her knee the world is made, and she bears Väinämöinen (Kalevala, Rune I).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.finnish.vainamoinen','Väinämöinen','万奈莫宁','Väinämöinen','Väinämöinen','HERO','civ.finnish','Kalevala (Lönnrot 1849, from oral poetry)','Ancient singer and sage of Kalevala, born old from Ilmatar after thirty summers in the womb; he sings Joukahainen into a swamp, seeks a bride in Pohjola, makes the first kantele and leads the theft of the Sampo (Kalevala, Runes I–L).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.finnish.ilmarinen','Ilmarinen','伊尔马里宁','Ilmarinen','Ilmarinen','HERO','civ.finnish','Kalevala (Lönnrot 1849, from oral poetry)','Eternal smith of Kalevala who forged the vault of the sky and forges the Sampo for the mistress of Pohjola to win her daughter (Kalevala, Runes X, XVIII–XXV, XXXVII–XLIII).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.finnish.joukahainen','Joukahainen','约卡海宁','Joukahainen','Joukahainen','HERO','civ.finnish','Kalevala (Lönnrot 1849, from oral poetry)','Young singer of the north who challenges Väinämöinen, is sung into a swamp and buys his life with the promise of his sister Aino; later he shoots Väinämöinen''s horse from under him (Kalevala, Runes III, VI).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.finnish.aino','Aino','艾诺','Aino','Aino','HERO','civ.finnish','Kalevala (Lönnrot 1849, from oral poetry)','Sister of Joukahainen promised against her will to the old Väinämöinen; she drowns in the sea and, caught by him as a strange fish, slips back into the waves (Kalevala, Runes IV–V).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.finnish.louhi','Louhi','洛希','Louhi','Louhi','HERO','civ.finnish','Kalevala (Lönnrot 1849, from oral poetry)','Gap-toothed mistress of Pohjola, a powerful sorceress who demands the Sampo as the price of her daughter and pursues its thieves as a great eagle (Kalevala, Runes VII, X, XLII–XLIII and elsewhere).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.finnish.maiden_of_pohjola','Maiden of Pohjola','波赫约拉的少女','Pohjan neiti','Maiden of Pohjola','HERO','civ.finnish','Kalevala (Lönnrot 1849, from oral poetry)','Daughter of Louhi, seen weaving on the rainbow, who sets Väinämöinen impossible tasks and later marries Ilmarinen (Kalevala, Runes VIII, X, XVIII–XXV, XXXIII).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('deity.finnish.ukko','Ukko','乌戈','Ukko','Ukko','DEITY','civ.finnish','Kalevala (Lönnrot 1849, from oral poetry)','Supreme sky god of the Kalevala, invoked for rain, hail, healing and help in need (Kalevala, passim).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('artifact.finnish.sampo','Sampo','三宝','Sampo','Sampo','ARTIFACT','civ.finnish','Kalevala (Lönnrot 1849, from oral poetry)','Wonder-mill with a many-coloured lid forged by Ilmarinen from a swan''s feather tip, a barren cow''s milk, a barley grain and a summer ewe''s wool; it grinds grain for eating, selling and storing, is locked in Pohjola''s mountain, stolen and shattered at sea (Kalevala, Runes X, XXXIX–XLIII).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('place.finnish.pohjola','Pohjola','波赫约拉','Pohjola','Pohjola','MYTHICAL_PLACE','civ.finnish','Kalevala (Lönnrot 1849, from oral poetry)','The cold northern land ruled by Louhi, where the heroes of Kalevala go to woo her daughter and where the Sampo is locked in a copper mountain (Kalevala, passim).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.finnish.lemminkainen','Lemminkäinen','勒明凯宁','Lemminkäinen','Lemminkäinen','HERO','civ.finnish','Kalevala (Lönnrot 1849, from oral poetry)','Handsome, reckless hero of Kalevala, also called Ahti and Kaukomieli, who carries off Kyllikki, goes to Pohjola to woo, is killed at the river of Tuonela and restored by his mother (Kalevala, Runes XI–XV, XXVI–XXX, XXXIX–XLIII).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.finnish.kyllikki','Kyllikki','基利基','Kyllikki','Kyllikki','HERO','civ.finnish','Kalevala (Lönnrot 1849, from oral poetry)','The flower of Saari, carried off by Lemminkäinen in his sledge; her broken vow not to go to the village dances sends him to Pohjola (Kalevala, Runes XI–XII).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.finnish.lemminkainen_mother','Mother of Lemminkäinen','勒明凯宁的母亲','Lemminkäisen äiti','Mother of Lemminkäinen','HERO','civ.finnish','Kalevala (Lönnrot 1849, from oral poetry)','Mother who warns Lemminkäinen against Pohjola, reads his death in the bleeding brush, rakes his body from the river of Tuonela and restores him to life (Kalevala, Runes XII, XV).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('person.finnish.markahattu','Märkähattu','马尔卡哈图（湿帽子）','Märkähattu','Märkähattu','PERSON','civ.finnish','Kalevala (Lönnrot 1849, from oral poetry)','Blind old herdsman of Pohjola scorned by Lemminkäinen, who waits at the river of Tuonela and kills him with a water-serpent (Kalevala, Runes XII, XIV).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('place.finnish.tuonela','Tuonela','图奥内拉（亡者之地）','Tuonela','Tuonela','REALM','civ.finnish','Kalevala (Lönnrot 1849, from oral poetry)','The land of the dead ruled by Tuoni, beyond a black river where the swan of Tuonela swims (Kalevala, Runes XIV–XVI).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.finnish.kullervo','Kullervo','库勒沃','Kullervo','Kullervo','HERO','civ.finnish','Kalevala (Lönnrot 1849, from oral poetry)','Son of Kalervo, born in captivity after his uncle Untamo destroys his kin; sold as a slave to Ilmarinen, he avenges the stone baked in his bread, unknowingly seduces his own sister, destroys Untamo''s clan and dies on his own sword (Kalevala, Runes XXXI–XXXVI).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('person.finnish.untamo','Untamo','温塔莫','Untamo','Untamo','PERSON','civ.finnish','Kalevala (Lönnrot 1849, from oral poetry)','Brother of Kalervo who, after a run of petty quarrels, destroys Kalervo''s people, fails three times to kill the infant Kullervo and sells him to Ilmarinen; his clan is later wiped out by Kullervo (Kalevala, Runes XXXI, XXXVI).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('person.finnish.kalervo','Kalervo','卡勒沃','Kalervo','Kalervo','PERSON','civ.finnish','Kalevala (Lönnrot 1849, from oral poetry)','Father of Kullervo, thought slain by his brother Untamo but found living with his family at the edge of Lapland (Kalevala, Runes XXXI, XXXIV–XXXVI).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('artifact.finnish.kantele','First kantele','第一把康特勒琴','kantele','First kantele','ARTIFACT','civ.finnish','Kalevala (Lönnrot 1849, from oral poetry)','Harp made by Väinämöinen from the jawbone of a giant pike, its pegs from the pike''s teeth and its strings from the hair of Hiisi''s gelding; its music moves all creatures to tears, and it is lost overboard in Louhi''s storm (Kalevala, Runes XL–XLIV).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('creature.finnish.iku_turso','Iku-Turso','伊库-图尔索','Iku-Turso','Iku-Turso','MONSTER','civ.finnish','Kalevala (Lönnrot 1849, from oral poetry)','Sea monster raised by Louhi against the boat carrying the Sampo; Väinämöinen lifts it by the ears and forbids it ever to rise from the sea again (Kalevala, Rune XLII).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.indian.nala','Nala','那罗','नल','Nala','HERO','civ.hindu','Mahābhārata (Sanskrit epic, composed c. 4th century BCE – 4th century CE)','King of the Nishadhas, chosen by Damayantī over four gods; possessed by Kali, he loses his kingdom at dice, abandons his wife in the forest, serves King Ṛtuparṇa as the charioteer Bāhuka and regains wife and kingdom (Mahābhārata, Vana Parva, Nalopākhyāna).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.indian.damayanti','Damayantī','达摩衍蒂','दमयन्ती','Damayantī','HERO','civ.hindu','Mahābhārata (Sanskrit epic, composed c. 4th century BCE – 4th century CE)','Princess of Vidarbha who chooses Nala at her svayaṃvara by recognising him among four gods in his likeness, survives abandonment in the forest and devises the second svayaṃvara that brings him back (Mahābhārata, Vana Parva, Nalopākhyāna).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('being.hindu.kali','Kali (personified age)','迦利（争斗时代的化身）','कलि','Kali (personified age)','SPIRIT','civ.hindu','Mahābhārata (Sanskrit epic, composed c. 4th century BCE – 4th century CE)','Personification of the dark age and of strife who, angry that Damayantī chose a mortal, waits twelve years for a lapse of Nala''s and enters him, driving him to ruin at dice until he is expelled (Mahābhārata, Vana Parva, Nalopākhyāna).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('creature.indian.karkotaka','Karkoṭaka','迦尔郭吒迦','कर्कोटक','Karkoṭaka','DIVINE_BEAST','civ.hindu','Mahābhārata (Sanskrit epic, composed c. 4th century BCE – 4th century CE)','Nāga rescued by Nala from a forest fire, who bites him to change his form and give him safety and a robe that will restore his shape (Mahābhārata, Vana Parva, Nalopākhyāna).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('person.indian.rituparna','Ṛtuparṇa','利图帕尔纳','ऋतुपर्ण','Ṛtuparṇa','PERSON','civ.hindu','Mahābhārata (Sanskrit epic, composed c. 4th century BCE – 4th century CE)','King of Ayodhyā who takes Nala as his charioteer Bāhuka, drives with him to Damayantī''s second svayaṃvara and teaches him the science of dice in exchange for the science of horses (Mahābhārata, Vana Parva, Nalopākhyāna).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('person.indian.pushkara','Pushkara','补湿迦罗','पुष्कर','Puṣkara','PERSON','civ.hindu','Mahābhārata (Sanskrit epic, composed c. 4th century BCE – 4th century CE)','Brother of Nala who, aided by Kali, wins Nala''s kingdom at dice and loses it back to him when Nala returns with the science of dice (Mahābhārata, Vana Parva, Nalopākhyāna).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.indian.savitri','Sāvitrī','莎维德丽','सावित्री','Sāvitrī','HERO','civ.hindu','Mahābhārata (Sanskrit epic, composed c. 4th century BCE – 4th century CE)','Daughter of King Aśvapati of Madra, born by the boon of the goddess Sāvitrī, who chooses the exiled prince Satyavān knowing he will die within a year, follows Yama when he takes Satyavān''s life, and wins it back by her steadfastness and wisdom (Mahābhārata, Vana Parva, Pativratā-māhātmya).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.indian.satyavan','Satyavān','萨谛梵','सत्यवान्','Satyavān','HERO','civ.hindu','Mahābhārata (Sanskrit epic, composed c. 4th century BCE – 4th century CE)','Son of the blind, exiled King Dyumatsena of Śālva, raised in a forest hermitage; foretold to die a year after his marriage to Sāvitrī, he is restored to life when Yama yields to her (Mahābhārata, Vana Parva, Pativratā-māhātmya).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('deity.hindu.yama','Yama','阎摩','यम','Yama','DEITY','civ.hindu','Mahābhārata (Sanskrit epic, composed c. 4th century BCE – 4th century CE)','God of death and of dharma, who comes himself with his noose for Satyavān''s life and, moved by Sāvitrī''s words as she follows him, grants her boons until he restores her husband (Mahābhārata, Vana Parva, Pativratā-māhātmya; also a suitor god in the Nala story).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('person.indian.ashvapati','Aśvapati','马主王','अश्वपति','Aśvapati','PERSON','civ.hindu','Mahābhārata (Sanskrit epic, composed c. 4th century BCE – 4th century CE)','Childless king of Madra who after eighteen years of offerings is granted a daughter, Sāvitrī, by the goddess Sāvitrī (Mahābhārata, Vana Parva, Pativratā-māhātmya).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('person.indian.dyumatsena','Dyumatsena','迪尤摩特舍那','द्युमत्सेन','Dyumatsena','PERSON','civ.hindu','Mahābhārata (Sanskrit epic, composed c. 4th century BCE – 4th century CE)','Blind king of Śālva driven from his throne, who lives in a forest hermitage with his son Satyavān; Sāvitrī''s boons restore his sight and his kingdom (Mahābhārata, Vana Parva, Pativratā-māhātmya).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.indian.yudhishthira','Yudhiṣṭhira','坚战','युधिष्ठिर','Yudhiṣṭhira','HERO','civ.hindu','Mahābhārata (Sanskrit epic, composed c. 4th century BCE – 4th century CE)','Eldest of the five Pāṇḍavas, son of Dharma, who loses the kingdom at dice, endures exile, and in the war speaks the half-truth that brings down Droṇa (Mahābhārata, passim).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.indian.bhima','Bhīma','怖军','भीम','Bhīma','HERO','civ.hindu','Mahābhārata (Sanskrit epic, composed c. 4th century BCE – 4th century CE)','Second of the Pāṇḍavas, son of Vāyu, of enormous strength, who vows vengeance for Draupadī''s humiliation and breaks Duryodhana''s thighs with his mace (Mahābhārata, passim).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.indian.draupadi','Draupadī','黑公主','द्रौपदी','Draupadī','HERO','civ.hindu','Mahābhārata (Sanskrit epic, composed c. 4th century BCE – 4th century CE)','Daughter of Drupada and wife of the five Pāṇḍavas, humiliated in the Kuru hall after the dice game, whose five sons are killed in Aśvatthāman''s night raid (Mahābhārata, passim).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('deity.hindu.krishna','Kṛṣṇa','黑天','कृष्ण','Kṛṣṇa','DEITY','civ.hindu','Mahābhārata (Sanskrit epic, composed c. 4th century BCE – 4th century CE)','Prince of the Yādavas and incarnation of Viṣṇu, cousin and counsellor of the Pāṇḍavas, who seeks peace as their envoy and drives Arjuna''s chariot at Kurukṣetra, teaching him the Bhagavad Gītā (Mahābhārata, passim).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.indian.bhishma','Bhīṣma','毗湿摩','भीष्म','Bhīṣma','HERO','civ.hindu','Mahābhārata (Sanskrit epic, composed c. 4th century BCE – 4th century CE)','Grandsire of the Kurus, son of Gaṅgā, bound by his vow of celibacy and his loyalty to the Kuru throne; first commander of the Kaurava army, he falls on the tenth day onto a bed of arrows and chooses the hour of his death (Mahābhārata, passim).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.indian.drona','Droṇa','德罗纳','द्रोण','Droṇa','HERO','civ.hindu','Mahābhārata (Sanskrit epic, composed c. 4th century BCE – 4th century CE)','Brahmin teacher of arms to both Kauravas and Pāṇḍavas and second commander of the Kaurava army, who lays down his weapons on hearing that Aśvatthāman is dead and is slain by Dhṛṣṭadyumna (Mahābhārata, passim).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.indian.karna','Karṇa','迦尔纳','कर्ण','Karṇa','HERO','civ.hindu','Mahābhārata (Sanskrit epic, composed c. 4th century BCE – 4th century CE)','Son of Kuntī by the sun god, raised by a charioteer, friend of Duryodhana and rival of Arjuna, who kills Ghaṭotkaca with Indra''s dart and is slain by Arjuna when his chariot wheel sinks (Mahābhārata, passim).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.indian.duryodhana','Duryodhana','难敌','दुर्योधन','Duryodhana','HERO','civ.hindu','Mahābhārata (Sanskrit epic, composed c. 4th century BCE – 4th century CE)','Eldest of the hundred Kaurava brothers, who wins the Pāṇḍavas'' kingdom through the rigged dice game, refuses peace, and is struck down by Bhīma''s mace at the end of the war (Mahābhārata, passim).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.indian.abhimanyu','Abhimanyu','激昂','अभिमन्यु','Abhimanyu','HERO','civ.hindu','Mahābhārata (Sanskrit epic, composed c. 4th century BCE – 4th century CE)','Young son of Arjuna and Subhadrā who breaks into the Kaurava circular array on the thirteenth day but, not knowing the way out, is killed by many warriors together (Mahābhārata, Drona Parva).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.indian.ashvatthama','Aśvatthāman','马嘶','अश्वत्थामा','Aśvatthāman','HERO','civ.hindu','Mahābhārata (Sanskrit epic, composed c. 4th century BCE – 4th century CE)','Son of Droṇa who, after the war, raids the sleeping Pāṇḍava camp by night, kills Dhṛṣṭadyumna and Draupadī''s sons, and is cursed by Kṛṣṇa (Mahābhārata, Drona and Sauptika Parvas).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.persian.sam','Sām','萨姆','سام','Sām','HERO','civ.persian','Shahnameh (Ferdowsi, completed c. 1010 CE)','Champion of King Manūchehr and lord of Zābulistān, who exposes his white-haired newborn son Zāl on Mount Alborz and, repenting after a dream, takes him back from the Simorgh (Shahnameh).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.persian.zal','Zāl','扎尔','زال','Zāl','HERO','civ.persian','Shahnameh (Ferdowsi, completed c. 1010 CE)','Son of Sām, born with white hair, exposed and raised by the Simorgh on Mount Alborz; he wins Rūdābeh of Kābul against his father''s and the king''s objections and fathers Rostam (Shahnameh).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('creature.persian.simorgh','Simorgh','西摩格','سیمرغ','Simorgh','DIVINE_BEAST','civ.persian','Shahnameh (Ferdowsi, completed c. 1010 CE)','Great wise bird of Mount Alborz who raises the exposed Zāl, gives him a feather to burn in need, and guides the birth of Rostam (Shahnameh).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.persian.rudabeh','Rūdābeh','鲁达贝','رودابه','Rūdābeh','HERO','civ.persian','Shahnameh (Ferdowsi, completed c. 1010 CE)','Daughter of Mehrāb of Kābul, a descendant of Zahhāk, who loves Zāl, offers her hair as a rope to her tower, and gives birth to Rostam by a cut made on the Simorgh''s counsel (Shahnameh).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('person.persian.mehrab','Mehrāb','梅赫拉布','مهراب','Mehrāb','PERSON','civ.persian','Shahnameh (Ferdowsi, completed c. 1010 CE)','King of Kābul descended from the tyrant Zahhāk, father of Rūdābeh and husband of Sindokht (Shahnameh).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('person.persian.sindokht','Sindokht','辛多赫特','سیندخت','Sindokht','PERSON','civ.persian','Shahnameh (Ferdowsi, completed c. 1010 CE)','Queen of Kābul, mother of Rūdābeh, who goes herself as envoy to Sām and wins his consent to the marriage of Zāl and Rūdābeh (Shahnameh).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('person.persian.manuchehr','Manūchehr','马努切赫尔','منوچهر','Manūchehr','PERSON','civ.persian','Shahnameh (Ferdowsi, completed c. 1010 CE)','Shah of Iran who receives the young Zāl, has his wise men test him with riddles, and consents to his marriage (Shahnameh).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.persian.rostam','Rostam','鲁斯塔姆','رستم','Rostam','HERO','civ.persian','Shahnameh (Ferdowsi, completed c. 1010 CE)','Greatest champion of the Shahnameh, son of Zāl and Rūdābeh, born by the Simorgh''s counsel; he rides Rakhsh, passes the seven stages to free Kay Kāvus and unknowingly kills his son Sohrāb (Shahnameh).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('creature.persian.rakhsh','Rakhsh','拉赫什','رخش','Rakhsh','DIVINE_BEAST','civ.persian','Shahnameh (Ferdowsi, completed c. 1010 CE)','Rose-dappled horse whom the young Rostam chooses and lassos, of whom the herdsman says his price is the land of Iran; he kills a lion and fights a dragon in the seven stages (Shahnameh).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('person.persian.kay_kavus','Kay Kāvus','凯·卡乌斯','کاووس','Kay Kāvus','PERSON','civ.persian','Shahnameh (Ferdowsi, completed c. 1010 CE)','Rash shah of Iran who, lured by a demon minstrel, invades Māzandarān and is blinded and captured by the White Demon until Rostam frees him; he later tries to fly to heaven on an eagle-drawn throne (Shahnameh).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('demon.persian.white_div','White Demon','白魔（迪弗·塞皮德）','دیو سپید','Div-e Sepid','DEMON','civ.persian','Shahnameh (Ferdowsi, completed c. 1010 CE)','Chief of the demons of Māzandarān who blinds and captures Kay Kāvus''s army with dark cloud and hail and is killed by Rostam in his cave; his blood restores the captives'' sight (Shahnameh).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('person.persian.olad','Olād','乌拉德','اولاد','Olād','PERSON','civ.persian','Shahnameh (Ferdowsi, completed c. 1010 CE)','Local lord of Māzandarān captured by Rostam in the fifth stage, who guides him to the White Demon and is afterwards made ruler of Māzandarān (Shahnameh).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('place.persian.mazandaran','Māzandarān','马赞德兰','مازندران','Māzandarān','MYTHICAL_PLACE','civ.persian','Shahnameh (Ferdowsi, completed c. 1010 CE)','Land of demons in the Shahnameh, praised by a demon minstrel to lure Kay Kāvus, ruled by a sorcerer king and guarded by the White Demon (Shahnameh).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.persian.tahmineh','Tahmineh','塔米娜','تهمینه','Tahmineh','HERO','civ.persian','Shahnameh (Ferdowsi, completed c. 1010 CE)','Princess of Samangān who comes to Rostam by night, marries him and bears Sohrāb; she gives her son the token by which his father should know him and dies of grief after his death (Shahnameh).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.persian.sohrab','Sohrāb','苏赫拉布','سهراب','Sohrāb','HERO','civ.persian','Shahnameh (Ferdowsi, completed c. 1010 CE)','Son of Rostam and Tahmineh, raised in Samangān, who leads a Turanian army into Iran hoping to set his father on the throne, and is killed by Rostam, neither knowing the other until too late (Shahnameh).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('person.persian.afrasiyab','Afrāsiyāb','阿夫拉西亚布','افراسیاب','Afrāsiyāb','PERSON','civ.persian','Shahnameh (Ferdowsi, completed c. 1010 CE)','King of Tūrān and enemy of Iran, who arms Sohrāb against Iran and charges his generals to keep father and son from knowing each other (Shahnameh).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.persian.gordafarid','Gordāfarid','戈尔达法丽德','گردآفرید','Gordāfarid','HERO','civ.persian','Shahnameh (Ferdowsi, completed c. 1010 CE)','Warrior maiden of the White Castle who rides out in armour against Sohrāb, is unmasked when he knocks off her helmet, and escapes him by a promise and a jest from the walls (Shahnameh).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.chinese.gan_jiang','Gan Jiang','干将','干將','Gan Jiang','HERO','civ.chinese_folk','Soushen ji (4th century CE)','Swordsmith of Chu who takes three years to forge a pair of swords for the king, hides the male sword for his unborn son, and is killed by the angry king (Soushen ji, juan 11).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.chinese.mo_ye','Mo Ye','莫邪','莫邪','Mo Ye','HERO','civ.chinese_folk','Soushen ji (4th century CE)','Wife of Gan Jiang who keeps her husband''s last words and tells their son where the hidden sword lies (Soushen ji, juan 11).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.chinese.chi_bi','Chi Bi','赤比','赤比','Chi Bi','HERO','civ.chinese_folk','Soushen ji (4th century CE)','Son of Gan Jiang and Mo Ye, ''a foot between the brows'', who gives his own head and sword to a stranger to avenge his father on the king of Chu; the three heads are buried as the Tomb of the Three Kings (Soushen ji, juan 11).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.chinese.dong_yong','Dong Yong','董永','董永','Dong Yong','HERO','civ.chinese_folk','Soushen ji (4th century CE)','Filial son of the Han who sells himself to bury his father and is helped to repay the debt by a wife who proves to be the Weaving Maiden of heaven (Soushen ji, juan 1).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('deity.chinese.zhinu','Weaving Maiden','织女','天之織女','Weaving Maiden','DEITY','civ.chinese_folk','Soushen ji (4th century CE)','Heavenly weaver sent by the Lord of Heaven to help the filial Dong Yong, who weaves a hundred bolts of silk in ten days and rises into the sky (Soushen ji, juan 1).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('deity.chinese.change','Chang''e','嫦娥（姮娥）','姮娥','Chang''e','DEITY','civ.chinese_folk','Soushen ji (4th century CE)','Wife of Yi who steals the elixir of immortality he obtained from the Queen Mother of the West and flees to the moon, where she becomes a toad (Soushen ji, juan 14).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('person.chinese.han_ping','Han Ping','韩凭','韓憑','Han Ping','PERSON','civ.chinese_folk','Soushen ji (4th century CE)','Retainer of King Kang of Song whose wife is taken by the king; husband and wife both die rather than be parted, and catalpa trees joined above their separate graves are called the trees of longing (Soushen ji, juan 11).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.chinese.ziyu','Ziyu','紫玉','紫玉','Ziyu','HERO','civ.chinese_folk','Soushen ji (4th century CE)','Youngest daughter of King Fuchai of Wu, who dies of grief when her father refuses Han Zhong, meets him as a ghost at her tomb, and appears to her father to clear him (Soushen ji, juan 16).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('person.chinese.song_dingbo','Song Dingbo','宋定伯','宋定伯','Song Dingbo','PERSON','civ.chinese_folk','Soushen ji (4th century CE)','Young man of Nanyang who meets a ghost by night, pretends to be a new ghost, learns that ghosts fear human spittle, and sells the ghost as a sheep in the market of Wan (Soushen ji, juan 16).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z'),
('hero.chinese.li_ji','Li Ji','李寄','李寄','Li Ji','HERO','civ.chinese_folk','Soushen ji (4th century CE)','Youngest of six daughters of Li Dan of Jiangle, who volunteers as the sacrifice to the great serpent of Mount Yong and kills it with a sword, a dog and honeyed rice cakes (Soushen ji, juan 19).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T18:00:00Z','2026-10-24T18:00:00Z');

