INSERT OR IGNORE INTO claims(
    id,subject_id,predicate,object_entity_id,object_literal,object_datatype,statement,variant_group,claim_status,confidence,confidence_level,review_status,assertion_scope,knowledge_layer,tradition_scope,temporal_scope,research_notes,created_at
) VALUES
('claim.v0350.kojiki_izanagi.01','deity.japanese.takamimusubi','NARRATIVE_ACTION',NULL,'comes into being among the first deities of High Heaven','string','Kojiki Section I says that when heaven and earth began, Ame-no-minaka-nushi, Takami-musubi and Kami-musubi came into being in the Plain of High Heaven, and that while the land drifted like floating oil two more deities sprouted like a reed-shoot.','v0350.kojiki_izanagi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_izanagi.02','deity.japanese.izanagi','NARRATIVE_ACTION','deity.japanese.izanami',NULL,NULL,'Kojiki Section II lists the Seven Divine Generations from Kuni-no-toko-tachi to the last pair, Izanagi and Izanami, counting each single deity and each pair as one generation.','v0350.kojiki_izanagi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_izanagi.03','deity.japanese.izanagi','NARRATIVE_ACTION','place.japanese.onogoro',NULL,NULL,'Kojiki Section III says the heavenly deities gave Izanagi and Izanami a jewelled spear, and that brine dripping from its point as they stirred from the Floating Bridge of Heaven piled up into Onogoro Island.','v0350.kojiki_izanagi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_izanagi.04','deity.japanese.izanami','NARRATIVE_ACTION',NULL,'speaks first at the heavenly pillar, and a leech-child is born','string','Kojiki Section IV says that after the two walked round the heavenly pillar and Izanami spoke first, their first child was a leech-child, put into a reed boat and floated away, and the island of Aha was not reckoned among their children.','v0350.kojiki_izanagi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_izanagi.05','deity.japanese.izanagi','NARRATIVE_ACTION','deity.japanese.izanami',NULL,NULL,'Kojiki Section V says the heavenly deities'' divination blamed the woman''s speaking first, and that when Izanagi spoke first at the pillar the pair gave birth to the eight great islands, from Awaji to Ō-yamato-toyo-aki-tsu-shima.','v0350.kojiki_izanagi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_izanagi.06','deity.japanese.izanami','NARRATIVE_ACTION',NULL,'bears the deities of sea, mountains, wind and trees','string','Kojiki Section VI says that after the islands Izanagi and Izanami bore many deities, among them the sea deity Ō-wata-tsu-mi, the mountain deity Ō-yama-tsu-mi, the Heavenly Bird-Boat and the food goddess Ō-ge-tsu-hime.','v0350.kojiki_izanagi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_izanagi.07','deity.japanese.izanami','NARRATIVE_ACTION','deity.japanese.kagutsuchi',NULL,NULL,'Kojiki Section VI says Izanami was burned in giving birth to the fire deity Kagutsuchi, that deities of metal, clay and water were born from her vomit, dung and urine as she lay sick, and that she then divinely retired.','v0350.kojiki_izanagi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_izanagi.08','deity.japanese.izanagi','NARRATIVE_ACTION','deity.japanese.kagutsuchi',NULL,NULL,'Kojiki Sections VII–VIII say Izanagi mourned Izanami, buried her on Mount Hiba, and cut off Kagutsuchi''s head with his ten-grasp sword, the blood near the guard becoming deities including Takemikazuchi.','v0350.kojiki_izanagi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_izanagi.09','deity.japanese.izanami','NARRATIVE_ACTION','place.japanese.yomi',NULL,NULL,'Kojiki Section IX says Izanami told Izanagi she had eaten the food of Yomi and asked him not to look at her, and that when he lit a comb-tooth and looked he saw maggots and eight thunder deities on her body.','v0350.kojiki_izanagi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_izanagi.10','deity.japanese.izanagi','NARRATIVE_ACTION',NULL,'escapes the pursuers of Yomi with grapes, bamboo shoots and three peaches','string','Kojiki Section IX says Izanagi escaped the Ugly Females of Yomi by throwing down a head-dress that became grapes and a comb that became bamboo shoots, and drove back the thunder deities'' host with three peaches at the foot of the Even Pass of Yomi.','v0350.kojiki_izanagi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_izanagi.11','deity.japanese.izanami','NARRATIVE_ACTION','deity.japanese.izanagi',NULL,NULL,'Kojiki Section IX says that across the rock blocking the Even Pass of Yomi Izanami vowed to strangle a thousand people a day and Izanagi answered he would set up fifteen hundred birth-houses a day, and that Izanami was thereafter called the Great Deity of Yomi.','v0350.kojiki_izanagi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_izanagi.12','deity.japanese.izanagi','NARRATIVE_ACTION',NULL,'purifies himself, and the three noble children are born of his washing','string','Kojiki Section X says Izanagi purified himself at the river-mouth of Tachibana in Himuka, deities being born from his discarded clothing and his washing, and last Amaterasu from his left eye, Tsukuyomi from his right eye and Susanoo from his nose.','v0350.kojiki_izanagi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_okuninushi.01','deity.japanese.okuninushi','NARRATIVE_ACTION','deity.japanese.susanoo',NULL,NULL,'Kojiki Section XX lists Susanoo''s descendants and gives Ōkuninushi''s five names: Ōkuninushi, Ōnamuji, Ashihara-shiko-wo, Yachihoko and Utsushi-kunitama.','v0350.kojiki_okuninushi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_okuninushi.02','deity.japanese.okuninushi','NARRATIVE_ACTION','creature.japanese.hare_of_inaba',NULL,NULL,'Kojiki Section XXI says Ōnamuji, carrying his brothers'' bag, healed the hare of Inaba with fresh water and sedge pollen after the Eighty Deities had made its injuries worse, and the hare foretold that Princess Yakami would choose him.','v0350.kojiki_okuninushi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_okuninushi.03','deity.japanese.kamimusubi','NARRATIVE_ACTION','deity.japanese.okuninushi',NULL,NULL,'Kojiki Section XXII says the Eighty Deities killed Ōnamuji by rolling down a red-hot boulder at Mount Tema, and Kami-musubi sent Princess Cockle-Shell and Princess Clam, who restored him to life.','v0350.kojiki_okuninushi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_okuninushi.04','deity.japanese.okuninushi','NARRATIVE_ACTION','place.japanese.ne_no_katasu_kuni',NULL,NULL,'Kojiki Section XXII says the Eighty Deities crushed Ōnamuji in a cleft tree, his mother restored him and sent him to Oho-ya-biko in Ki, who let him escape through the fork of a tree towards Susanoo''s Nether-Distant-Land.','v0350.kojiki_okuninushi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_okuninushi.05','deity.japanese.suseribime','NARRATIVE_ACTION','deity.japanese.okuninushi',NULL,NULL,'Kojiki Section XXIII says Suseri-bime married Ōnamuji when he arrived, and when Susanoo made him sleep in the snake room she gave him a snake-scarf to wave three times, so that he came out unharmed.','v0350.kojiki_okuninushi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_okuninushi.06','deity.japanese.suseribime','NARRATIVE_ACTION',NULL,'gives her husband a scarf against centipedes and wasps','string','Kojiki Section XXIII says that when Susanoo next put Ōnamuji in a room of centipedes and wasps, Suseri-bime again gave him a scarf against them and he came out unharmed.','v0350.kojiki_okuninushi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_okuninushi.07','deity.japanese.okuninushi','NARRATIVE_ACTION','deity.japanese.susanoo',NULL,NULL,'Kojiki Section XXIII says that when Susanoo set fire to the moor around Ōnamuji, a mouse showed him a hollow in the ground to shelter in and brought back the whizzing arrow, and he presented the arrow to Susanoo.','v0350.kojiki_okuninushi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_okuninushi.08','deity.japanese.suseribime','NARRATIVE_ACTION','deity.japanese.susanoo',NULL,NULL,'Kojiki Section XXIII says that when Susanoo made Ōnamuji pick centipedes from his hair, Suseri-bime gave him muku berries and red earth to chew and spit, so that Susanoo fell asleep pleased with him.','v0350.kojiki_okuninushi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_okuninushi.09','deity.japanese.susanoo','NARRATIVE_ACTION','deity.japanese.okuninushi',NULL,NULL,'Kojiki Section XXIII says Ōnamuji escaped with Suseri-bime and Susanoo''s sword, bow and speaking lute, and Susanoo, pursuing to the Even Pass of Yomi, called on him to drive away his brothers, become Ōkuninushi and make Suseri-bime his chief wife.','v0350.kojiki_okuninushi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_okuninushi.10','deity.japanese.okuninushi','NARRATIVE_ACTION','deity.japanese.suseribime',NULL,NULL,'Kojiki Sections XXIV–XXV say that as Yachihoko he wooed Princess Nunakawa of Koshi with songs, and that when Suseri-bime was jealous they exchanged songs and pledged each other with a wine-cup.','v0350.kojiki_okuninushi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_okuninushi.11','deity.japanese.sukunabikona','NARRATIVE_ACTION','deity.japanese.okuninushi',NULL,NULL,'Kojiki Section XXVII says Sukuna-bikona came over the waves to Cape Miho in a seed-pod boat, Kami-musubi named him her child who slipped through her fingers, and he made the land with Ōkuninushi before crossing to the Eternal Land.','v0350.kojiki_okuninushi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_okuninushi.12','deity.japanese.okuninushi','NARRATIVE_ACTION',NULL,'enshrines the deity from the sea on Mount Mimoro','string','Kojiki Section XXVIII says that after Sukuna-bikona left, a deity came over the sea illuminating it and offered to make the land with Ōkuninushi if worshipped on the eastern mountain of Yamato, the deity of Mount Mimoro.','v0350.kojiki_okuninushi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_okuninushi.13','deity.japanese.ame_no_wakahiko','NARRATIVE_ACTION','deity.japanese.takamimusubi',NULL,NULL,'Kojiki Sections XXX–XXXI say Ame-no-hohi and then Ame-no-Wakahiko failed to report from the Central Land, and that when Ame-no-Wakahiko shot the pheasant Naki-me, Takagi-no-kami threw the arrow back and it killed him on his bed.','v0350.kojiki_okuninushi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_okuninushi.14','deity.japanese.takemikazuchi','NARRATIVE_ACTION','deity.japanese.okuninushi',NULL,NULL,'Kojiki Section XXXII says Takemikazuchi, seated on an upturned sword on a wave at Inasa, demanded the land; Kotoshironushi agreed, Takeminakata was overpowered and fled to Suwa, and Ōkuninushi yielded the land on condition that a great palace be built for him.','v0350.kojiki_okuninushi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_ninigi.01','deity.japanese.ninigi','NARRATIVE_ACTION','deity.japanese.amaterasu',NULL,NULL,'Kojiki Section XXXIII says that when the land was reported pacified, Ame-no-oshi-ho-mimi proposed his newborn son Ninigi in his place, and Amaterasu and Takagi-no-kami commanded Ninigi to descend and rule the Land of Fresh Rice-Ears.','v0350.kojiki_ninigi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_ninigi.02','deity.japanese.sarutahiko','NARRATIVE_ACTION','deity.japanese.ame_no_uzume',NULL,NULL,'Kojiki Section XXXIII says that a deity shining up to High Heaven and down to the Central Land stood at the heavenly crossroads, and when Ame-no-Uzume questioned him he named himself the earthly deity Sarutahiko, come to guide the August Grandchild.','v0350.kojiki_ninigi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_ninigi.03','deity.japanese.amaterasu','NARRATIVE_ACTION','deity.japanese.ninigi',NULL,NULL,'Kojiki Section XXXIII says Amaterasu sent five chiefs of companies with Ninigi and gave him the curved jewels, the mirror and the Kusanagi sword, charging him to reverence the mirror as her own spirit.','v0350.kojiki_ninigi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_ninigi.04','deity.japanese.ninigi','NARRATIVE_ACTION',NULL,'descends on the peak of Takachiho in Himuka','string','Kojiki Sections XXXIII–XXXIV say Ninigi pushed through the eight-fold clouds and descended on the peak of Kuji-furu-take of Takachiho in Himuka, called the place exceedingly good, and built his palace there.','v0350.kojiki_ninigi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_ninigi.05','deity.japanese.ame_no_uzume','NARRATIVE_ACTION','deity.japanese.sarutahiko',NULL,NULL,'Kojiki Sections XXXV–XXXVI say Ame-no-Uzume escorted Sarutahiko home and took his name for the Duchesses of Saru, that Sarutahiko drowned when a shell caught his hand at Azaka, and that she slit the mouth of the sea-slug that would not answer.','v0350.kojiki_ninigi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_ninigi.06','deity.japanese.oyamatsumi','NARRATIVE_ACTION','deity.japanese.ninigi',NULL,NULL,'Kojiki Section XXXVII says Ōyamatsumi sent both his daughters to Ninigi, and when Ninigi returned the ugly Iwanaga-hime and kept Konohana-sakuya-hime, he declared that the lives of the heavenly deity''s descendants would be as brief as blossoms.','v0350.kojiki_ninigi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_ninigi.07','deity.japanese.konohana_sakuya_hime','NARRATIVE_ACTION','deity.japanese.ninigi',NULL,NULL,'Kojiki Section XXXVIII says that when Ninigi doubted the child conceived in one night, Konohana-sakuya-hime gave birth inside a sealed, burning doorless hall to Hoderi, Hosuseri and Hoori.','v0350.kojiki_ninigi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_ninigi.08','deity.japanese.hoori','NARRATIVE_ACTION','deity.japanese.hoderi',NULL,NULL,'Kojiki Section XXXIX says Hoori persuaded his brother Hoderi to exchange their gear, lost the fish-hook at sea, and could not make his brother accept five hundred or a thousand hooks forged from his sword in its place.','v0350.kojiki_ninigi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_ninigi.09','deity.japanese.hoori','NARRATIVE_ACTION','place.japanese.watatsumi_palace',NULL,NULL,'Kojiki Section XL says the salt deity Shio-tsuchi set Hoori in a tightly woven bamboo boat and told him to follow the current to the sea deity''s palace built like fish-scales and sit in the cassia tree by its well.','v0350.kojiki_ninigi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_ninigi.10','deity.japanese.toyotama_hime','NARRATIVE_ACTION','deity.japanese.hoori',NULL,NULL,'Kojiki Section XL says Hoori spat a jewel into the vessel of Toyotama-bime''s maid at the well, Toyotama-bime fell in love with him at sight, and the sea deity welcomed him on layered rugs and gave her to him in marriage.','v0350.kojiki_ninigi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_ninigi.11','deity.japanese.watatsumi','NARRATIVE_ACTION','artifact.japanese.tide_jewels',NULL,NULL,'Kojiki Sections XL–XLI say the sea deity found the hook in a sea-bream''s throat, gave Hoori the tide-flowing and tide-ebbing jewels with counsel, and that Hoori used them to subdue Hoderi, who vowed to be his guard.','v0350.kojiki_ninigi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_ninigi.12','deity.japanese.toyotama_hime','NARRATIVE_ACTION','deity.japanese.hoori',NULL,NULL,'Kojiki Sections XLII–XLIII say Toyotama-bime gave birth in an unfinished hut thatched with cormorant feathers, was seen by Hoori in her true form as an eight-fathom wani, and in shame closed the sea-boundary and returned to the sea, leaving her son Ugaya-fuki-aezu.','v0350.kojiki_ninigi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_yamato_takeru.01','person.japanese.keiko','NARRATIVE_ACTION','hero.japanese.yamato_takeru',NULL,NULL,'Kojiki Section LXXIX says that when Keikō asked Wo-usu to teach his elder brother Oho-usu to come to meals, Wo-usu killed his brother, and the sovereign was afraid of his son''s fierce heart.','v0350.kojiki_yamato_takeru','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_yamato_takeru.02','hero.japanese.yamato_takeru','NARRATIVE_ACTION','hero.japanese.yamato_hime',NULL,NULL,'Kojiki Section LXXX says Wo-usu, sent west against the Kumaso bravoes, took his aunt Yamato-hime''s robe and skirt, let down his hair like a girl''s and entered their housewarming feast, where they seated him between them.','v0350.kojiki_yamato_takeru','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_yamato_takeru.03','person.japanese.kumaso_takeru','NARRATIVE_ACTION','hero.japanese.yamato_takeru',NULL,NULL,'Kojiki Section LXXX says Wo-usu killed both Kumaso bravoes at their feast, and that the dying younger brother, saying there was a braver man in Yamato than they, gave him the name Yamato Takeru.','v0350.kojiki_yamato_takeru','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_yamato_takeru.04','person.japanese.izumo_takeru','NARRATIVE_ACTION','hero.japanese.yamato_takeru',NULL,NULL,'Kojiki Section LXXXI says Yamato Takeru befriended the Izumo bravo, made a false wooden sword, exchanged swords with him after bathing in the river Hi, and killed him when he could not draw it.','v0350.kojiki_yamato_takeru','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_yamato_takeru.05','hero.japanese.yamato_hime','NARRATIVE_ACTION','weapon.japanese.kusanagi',NULL,NULL,'Kojiki Section LXXXII says that when Yamato Takeru, sent east at once without troops, wept at Ise that his father wished him dead, his aunt Yamato-hime gave him the Kusanagi sword and a bag to open in an emergency.','v0350.kojiki_yamato_takeru','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_yamato_takeru.06','hero.japanese.yamato_takeru','NARRATIVE_ACTION','weapon.japanese.kusanagi',NULL,NULL,'Kojiki Section LXXXIII says that when the ruler of Sagamu set fire to the moor around him, Yamato Takeru opened his aunt''s bag, mowed the grass with his sword and lit a counter-fire with the fire-striker, then killed the rulers, so that the place is called Yaizu.','v0350.kojiki_yamato_takeru','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_yamato_takeru.07','hero.japanese.oto_tachibana_hime','NARRATIVE_ACTION','hero.japanese.yamato_takeru',NULL,NULL,'Kojiki Section LXXXIV says that when the deity of the Hashirimizu strait raised waves against the boat, Oto-tachibana-hime spread rugs on the waves and entered the sea in Yamato Takeru''s stead, the waves calmed, and seven days later her comb drifted ashore.','v0350.kojiki_yamato_takeru','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_yamato_takeru.08','hero.japanese.yamato_takeru','NARRATIVE_ACTION',NULL,'sighs ''Azuma haya'' on the Ashigara pass, naming the East','string','Kojiki Section LXXXV says Yamato Takeru killed the deity of the Ashigara pass, which came as a white deer, with a wild chive, and on the pass sighed three times ''Azuma haya'', so that the land is called Azuma.','v0350.kojiki_yamato_takeru','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_yamato_takeru.09','hero.japanese.yamato_takeru','NARRATIVE_ACTION',NULL,'completes a verse with an old fire-keeper at Sakaori','string','Kojiki Section LXXXVI says that at the palace of Sakaori in Kai, when Yamato Takeru asked in verse how many nights had passed since Niibari and Tsukuba, an old fire-keeper answered nine nights and ten days, and was made ruler of the East.','v0350.kojiki_yamato_takeru','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_yamato_takeru.10','deity.japanese.ibuki_deity','NARRATIVE_ACTION','hero.japanese.yamato_takeru',NULL,NULL,'Kojiki Sections LXXXVII–LXXXVIII say Yamato Takeru married Miyazu-hime, left the Kusanagi sword with her and went bare-handed against Mount Ibuki, where he took the deity in the form of a white boar for its messenger and was struck senseless by hail.','v0350.kojiki_yamato_takeru','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_yamato_takeru.11','hero.japanese.yamato_takeru','NARRATIVE_ACTION',NULL,'names the places of his last journey as his strength fails','string','Kojiki Section LXXXIX says Yamato Takeru, weakened, named the Awakening Spring, Tagi and the Staff Slope, found his forgotten sword still under the pine of Cape Otsu, and at Mie said his legs were like a thrice-bent rice cake.','v0350.kojiki_yamato_takeru','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kojiki_yamato_takeru.12','hero.japanese.yamato_takeru','NARRATIVE_ACTION',NULL,'dies at Nobo and turns into a great white bird','string','Kojiki Sections LXXXIX–XC say Yamato Takeru died at Nobo after singing of his longing for Yamato and of the sword left by the maiden''s bed, and that he turned into a great white bird that flew towards the shore, stopped at Shiki and rose into the sky again.','v0350.kojiki_yamato_takeru','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_1.01','deity.finnish.ilmatar','NARRATIVE_ACTION',NULL,'floats on the primeval sea; the world is made from the duck''s broken eggs','string','Kalevala Rune I says Ilmatar, daughter of the air, floated on the sea as Water-mother, that a duck laid six golden eggs and one of iron on her raised knee, and that the broken eggs became the earth, the sky, the sun, the moon, the stars and the clouds.','v0350.kal_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_1.02','hero.finnish.vainamoinen','NARRATIVE_ACTION','deity.finnish.ilmatar',NULL,NULL,'Kalevala Rune I says Ilmatar shaped the headlands, bays and shores, and that Väinämöinen, after thirty summers in her womb, forced his way out, drifted on the sea for years and came ashore already old.','v0350.kal_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_1.03','hero.finnish.vainamoinen','NARRATIVE_ACTION',NULL,'has the forests sown, the great oak felled and the barley grown','string','Kalevala Rune II says Väinämöinen had Sampsa Pellervoinen sow the forests, that a little man from the sea grew into a giant and felled the oak that hid the sun and moon, and that Väinämöinen cleared the land for barley, sparing a birch for the birds.','v0350.kal_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_1.04','hero.finnish.vainamoinen','NARRATIVE_ACTION','hero.finnish.joukahainen',NULL,NULL,'Kalevala Rune III says that when the young Joukahainen challenged Väinämöinen to a contest of wisdom and then to a fight, Väinämöinen sang his sledge, horse and weapons into other shapes and sank him into a swamp up to his chin.','v0350.kal_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_1.05','hero.finnish.joukahainen','NARRATIVE_ACTION','hero.finnish.aino',NULL,NULL,'Kalevala Runes III–IV say that Joukahainen, sinking in the swamp, offered bows, boats, horses, gold and fields and at last his sister Aino, whereupon Väinämöinen sang him free; his mother rejoiced, but Aino wept.','v0350.kal_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_1.06','hero.finnish.aino','NARRATIVE_ACTION',NULL,'drowns rather than marry the old Väinämöinen','string','Kalevala Rune IV says Aino, refusing to marry the old Väinämöinen, swam out to a rock in the sea that sank with her, and that her mother''s tears became three rivers by which three birches and three cuckoos appeared.','v0350.kal_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_1.07','hero.finnish.aino','NARRATIVE_ACTION','hero.finnish.vainamoinen',NULL,NULL,'Kalevala Rune V says Väinämöinen caught a strange fish that leapt back into the sea and told him it was Aino, whom he had failed to recognise, and that his dead mother then advised him to seek a bride in Pohjola.','v0350.kal_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_1.08','hero.finnish.joukahainen','NARRATIVE_ACTION','hero.finnish.vainamoinen',NULL,NULL,'Kalevala Rune VI says Joukahainen lay in wait with a steel bow against his mother''s warning, and that his third arrow struck Väinämöinen''s horse so that Väinämöinen fell into the sea and was swept away.','v0350.kal_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_1.09','hero.finnish.louhi','NARRATIVE_ACTION','artifact.finnish.sampo',NULL,NULL,'Kalevala Rune VII says an eagle, remembering the birch he spared, carried Väinämöinen to Pohjola, where Louhi promised to send him home and give her daughter for the forging of a Sampo, which he said only Ilmarinen could make.','v0350.kal_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_1.10','hero.finnish.maiden_of_pohjola','NARRATIVE_ACTION','hero.finnish.vainamoinen',NULL,NULL,'Kalevala Rune VIII says the maiden of Pohjola, weaving on the rainbow, set Väinämöinen impossible tasks, and that while building a boat from her spindle his axe, misguided by evil spirits, cut deep into his knee.','v0350.kal_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_1.11','hero.finnish.vainamoinen','NARRATIVE_ACTION','hero.finnish.ilmarinen',NULL,NULL,'Kalevala Rune IX says an old man healed Väinämöinen''s knee after Väinämöinen told the origin of iron — born of three maidens'' milk, forged by Ilmarinen and made fierce when Hiisi''s hornet poisoned the tempering water.','v0350.kal_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_1.12','hero.finnish.ilmarinen','NARRATIVE_ACTION','artifact.finnish.sampo',NULL,NULL,'Kalevala Rune X says Väinämöinen tricked Ilmarinen into going to Pohjola, where after rejecting a bow, a boat, a heifer and a plough he forged the Sampo with its many-coloured lid, which Louhi locked in her stone mountain while the maiden refused him.','v0350.kal_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_2.01','hero.finnish.lemminkainen','NARRATIVE_ACTION','hero.finnish.kyllikki',NULL,NULL,'Kalevala Rune XI says the reckless Lemminkäinen went to the island of Saari to woo Kyllikki, who had refused the sons of the sun, moon and stars, and befriended all the island maidens except her.','v0350.kal_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_2.02','hero.finnish.lemminkainen','NARRATIVE_ACTION','hero.finnish.kyllikki',NULL,NULL,'Kalevala Rune XI says Lemminkäinen carried Kyllikki off in his sledge, and that they swore before Ukko that he would never go to war and she would never go dancing in the village.','v0350.kal_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_2.03','hero.finnish.kyllikki','NARRATIVE_ACTION','hero.finnish.lemminkainen',NULL,NULL,'Kalevala Rune XII says Kyllikki broke her vow and went dancing in the village while Lemminkäinen was fishing, and that when his sister Ainikki told him he declared himself free of his own oath and set out for Pohjola.','v0350.kal_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_2.04','hero.finnish.lemminkainen','NARRATIVE_ACTION','hero.finnish.lemminkainen_mother',NULL,NULL,'Kalevala Rune XII says that, ignoring his mother''s warnings, Lemminkäinen threw down his brush saying that when it dripped blood misfortune would have befallen him, and drove north to Pohjola.','v0350.kal_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_2.05','hero.finnish.lemminkainen','NARRATIVE_ACTION','person.finnish.markahattu',NULL,NULL,'Kalevala Rune XII says Lemminkäinen sang all the sorcerers of Pohjola away except the old blind herdsman Märkähattu, whom he mocked, and who went in hatred to wait by the river of Tuonela.','v0350.kal_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_2.06','hero.finnish.lemminkainen','NARRATIVE_ACTION','hero.finnish.louhi',NULL,NULL,'Kalevala Rune XIII says Louhi set Lemminkäinen the task of catching the elk of Hiisi on skis, and that he chased the elk Hiisi had made into Lapland until his ski and pole broke and the elk escaped.','v0350.kal_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_2.07','hero.finnish.lemminkainen','NARRATIVE_ACTION',NULL,'catches the elk of Hiisi after praying to the forest gods','string','Kalevala Rune XIV says that after praying for three days to the forest gods Tapio and Mielikki, Lemminkäinen caught the elk of Hiisi and brought it to Louhi, who then set him a second task.','v0350.kal_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_2.08','hero.finnish.lemminkainen','NARRATIVE_ACTION','deity.finnish.ukko',NULL,NULL,'Kalevala Rune XIV says that when Louhi set him to bridle Hiisi''s fire-breathing gelding, Lemminkäinen prayed Ukko to quench it with hail and then bridled it with a golden halter.','v0350.kal_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_2.09','person.finnish.markahattu','NARRATIVE_ACTION','hero.finnish.lemminkainen',NULL,NULL,'Kalevala Rune XIV says that when Lemminkäinen went to shoot the swan of Tuonela, the blind herdsman Märkähattu, lying in wait, pierced his heart with a water-serpent, and he lamented that he had never learned the charm against it.','v0350.kal_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_2.10','place.finnish.tuonela','NARRATIVE_ACTION','hero.finnish.lemminkainen',NULL,NULL,'Kalevala Rune XIV says the herdsman threw the dying Lemminkäinen into the black river of Tuonela, where the son of Tuoni hewed him into pieces and cast them into its depths.','v0350.kal_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_2.11','hero.finnish.lemminkainen_mother','NARRATIVE_ACTION','hero.finnish.louhi',NULL,NULL,'Kalevala Rune XV says that when the brush dripped blood Lemminkäinen''s mother hurried to Pohjola, forced Louhi to tell where she had sent him, and after the trees, the road and the moon could not help, learned from the sun that he lay hewn in pieces in the river of Tuonela.','v0350.kal_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_2.12','hero.finnish.lemminkainen_mother','NARRATIVE_ACTION','hero.finnish.lemminkainen',NULL,NULL,'Kalevala Rune XV says Lemminkäinen''s mother raked her son''s body piece by piece from the river of Tuonela with a copper rake forged by Ilmarinen, had his veins joined, and revived him with the Creator''s honey brought by a bee from beyond the nine heavens.','v0350.kal_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_3.01','person.finnish.untamo','NARRATIVE_ACTION','person.finnish.kalervo',NULL,NULL,'Kalevala Rune XXXI says the brothers Untamo and Kalervo quarrelled over a run of petty matters until Untamo slew Kalervo''s people, sparing only a pregnant woman whom he took as a slave.','v0350.kal_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_3.02','hero.finnish.kullervo','NARRATIVE_ACTION','person.finnish.untamo',NULL,NULL,'Kalevala Rune XXXI says Kullervo, born to the captive woman in Untamo''s house, broke his swaddling and cradle in his third month and was heard vowing to avenge his father, so that Untamo resolved to kill him.','v0350.kal_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_3.03','person.finnish.untamo','NARRATIVE_ACTION','hero.finnish.kullervo',NULL,NULL,'Kalevala Rune XXXI says Untamo tried to kill the young Kullervo in a barrel thrown into the lake, on a burning pyre and hanged from an oak, and each time found him alive — fishing, stirring the embers, carving warriors on the tree.','v0350.kal_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_3.04','person.finnish.untamo','NARRATIVE_ACTION','hero.finnish.kullervo',NULL,NULL,'Kalevala Rune XXXI says Kullervo ruined every task Untamo set him — minding a child, clearing the forest, building a fence, threshing the rye — and that Untamo sold him to the smith Ilmarinen in Karelia for worn-out kettles and old tools.','v0350.kal_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_3.05','hero.finnish.maiden_of_pohjola','NARRATIVE_ACTION','hero.finnish.kullervo',NULL,NULL,'Kalevala Rune XXXII says Ilmarinen''s wife sent Kullervo to herd the cattle with a loaf in which she had baked a stone, after praying to Ukko and the forest spirits to protect her herd.','v0350.kal_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_3.06','hero.finnish.kullervo','NARRATIVE_ACTION',NULL,'breaks his father''s knife on the stone and turns wolves and bears into cattle','string','Kalevala Rune XXXIII says Kullervo''s father''s knife, his only keepsake, broke on the stone in the loaf, and that on a crow''s advice he let wolves and bears devour the herd and drove them home in the shape of cattle.','v0350.kal_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_3.07','hero.finnish.kullervo','NARRATIVE_ACTION','hero.finnish.maiden_of_pohjola',NULL,NULL,'Kalevala Rune XXXIII says Ilmarinen''s wife was mauled by the beasts when she went to milk them, that Kullervo refused to save her, reproaching her for the stone in his bread, and that he then fled into the forest.','v0350.kal_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_3.08','hero.finnish.kullervo','NARRATIVE_ACTION','person.finnish.kalervo',NULL,NULL,'Kalevala Rune XXXIV says an old woman in a blue robe told the fleeing Kullervo that his parents lived at the edge of Lapland, where he found them, and learned that his elder sister had vanished long ago while picking berries.','v0350.kal_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_3.09','hero.finnish.kullervo','NARRATIVE_ACTION','person.finnish.kalervo',NULL,NULL,'Kalevala Rune XXXV says Kullervo, useless at his father''s work, was sent to pay the taxes, and on his way home lured a maiden into his sledge who next morning learned that she was Kalervo''s lost daughter, his own sister.','v0350.kal_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_3.10','hero.finnish.kullervo','NARRATIVE_ACTION',NULL,'loses his sister to the rapids and resolves on vengeance','string','Kalevala Rune XXXV says Kullervo''s sister threw herself into the rapids when she learned the truth, and that Kullervo, though his mother begged him to live, resolved first to take vengeance on Untamo.','v0350.kal_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_3.11','hero.finnish.kullervo','NARRATIVE_ACTION','person.finnish.untamo',NULL,NULL,'Kalevala Rune XXXVI says only Kullervo''s mother promised to weep for him, that he wept only when told of her death, and that with a sword from Ukko he destroyed Untamo''s clan and burned their dwellings.','v0350.kal_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_3.12','hero.finnish.kullervo','NARRATIVE_ACTION','hero.finnish.vainamoinen',NULL,NULL,'Kalevala Rune XXXVI says Kullervo, finding his family dead, went with his dog to the place where he had wronged his sister, and after his sword answered that it would drink his guilty blood, fell upon it; Väinämöinen then warns against raising a child wrongly.','v0350.kal_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_4.01','hero.finnish.ilmarinen','NARRATIVE_ACTION','hero.finnish.vainamoinen',NULL,NULL,'Kalevala Rune XXXIX says Väinämöinen persuaded Ilmarinen to go and win back the Sampo, that Ilmarinen forged him a sword adorned with the moon, the sun and the stars, and that they launched by song a war-boat that wept to go to war.','v0350.kal_4','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_4.02','hero.finnish.lemminkainen','NARRATIVE_ACTION','hero.finnish.vainamoinen',NULL,NULL,'Kalevala Rune XXXIX says that Lemminkäinen, idle on a headland for want of war, hailed the boat and asked to come as the third hero, and that Väinämöinen took him aboard to go for the Sampo.','v0350.kal_4','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_4.03','hero.finnish.vainamoinen','NARRATIVE_ACTION',NULL,'kills the giant pike that holds the boat fast','string','Kalevala Rune XL says the heroes'' boat stuck on the back of a giant pike in the rapids, that Lemminkäinen and Ilmarinen failed to harm it, and that Väinämöinen pierced and lifted it with his sword.','v0350.kal_4','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_4.04','hero.finnish.vainamoinen','NARRATIVE_ACTION','artifact.finnish.kantele',NULL,NULL,'Kalevala Rune XL says Väinämöinen made the first kantele from the giant pike''s jawbone, with its teeth for pegs and hair from Hiisi''s gelding for strings, and that no one else could draw a fair tune from it.','v0350.kal_4','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_4.05','hero.finnish.vainamoinen','NARRATIVE_ACTION','artifact.finnish.kantele',NULL,NULL,'Kalevala Rune XLI says that when Väinämöinen played the kantele every creature came to listen — the beasts and Tapio of the forest, the birds, the fishes, Ahto king of the sea, and the daughters of the moon and sun, who dropped their spindles.','v0350.kal_4','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_4.06','hero.finnish.vainamoinen','NARRATIVE_ACTION',NULL,'weeps tears that become blue pearls','string','Kalevala Rune XLI says that all who heard the kantele wept, and that Väinämöinen''s own tears rolled into the sea, from which a blue duck brought them up changed into blue pearls.','v0350.kal_4','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_4.07','hero.finnish.louhi','NARRATIVE_ACTION','hero.finnish.vainamoinen',NULL,NULL,'Kalevala Rune XLII says Louhi refused to share the Sampo and called her warriors, and that Väinämöinen played the kantele until all the people of Pohjola fell asleep.','v0350.kal_4','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_4.08','hero.finnish.ilmarinen','NARRATIVE_ACTION','artifact.finnish.sampo',NULL,NULL,'Kalevala Rune XLII says the heroes opened the copper mountain''s doors by song, Ilmarinen buttering the hinges, and when Lemminkäinen could not lift the Sampo they ploughed through its roots with the great ox of Pohjola and carried it to their boat.','v0350.kal_4','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_4.09','hero.finnish.lemminkainen','NARRATIVE_ACTION',NULL,'sings against warning and wakes Pohjola through a crane','string','Kalevala Rune XLII says that on the third day Lemminkäinen, against Väinämöinen''s warning, burst into harsh song, and a startled crane flew screaming to Pohjola and woke its people, so that Louhi found the Sampo gone.','v0350.kal_4','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_4.10','hero.finnish.louhi','NARRATIVE_ACTION','creature.finnish.iku_turso',NULL,NULL,'Kalevala Rune XLII says Louhi sent fog, which Väinämöinen cut with his sword, raised the sea monster Iku-Turso, which he banished by the ears, and called up a storm that swept his kantele into the sea.','v0350.kal_4','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_4.11','hero.finnish.louhi','NARRATIVE_ACTION','hero.finnish.vainamoinen',NULL,NULL,'Kalevala Rune XLIII says Louhi pursued the heroes as a giant eagle carrying her warriors, and that Väinämöinen smashed her talons with the rudder so that her warriors fell into the sea.','v0350.kal_4','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.kal_4.12','artifact.finnish.sampo','NARRATIVE_ACTION',NULL,'shatters in the sea, enriching the sea and Kalevala','string','Kalevala Rune XLIII says the Sampo fell from the boat as Louhi clutched it and shattered in the sea, its large pieces becoming the sea''s riches and its small pieces drifting to Kalevala, where Väinämöinen planted them, while Louhi took home only the lid.','v0350.kal_4','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kalevala (Crawford translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_nala.01','hero.indian.nala','NARRATIVE_ACTION',NULL,'is the subject of the tale told to the exiled Yudhiṣṭhira','string','Mahābhārata, Vana Parva, Section LII says that when the exiled Yudhiṣṭhira lamented that no king was more unfortunate, the sage Bṛhadaśva offered to tell him of Nala, who also lost his kingdom at dice and regained it.','v0350.mbh_nala','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_nala.02','hero.indian.damayanti','NARRATIVE_ACTION','hero.indian.nala',NULL,NULL,'Mahābhārata, Vana Parva, Section LIII says Nala and Damayantī came to love each other through report, and that a golden-winged swan released by Nala carried praise of each to the other.','v0350.mbh_nala','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_nala.03','deity.vedic.indra','NARRATIVE_ACTION','hero.indian.nala',NULL,NULL,'Mahābhārata, Vana Parva, Section LIV says Indra, Agni, Varuṇa and Yama, going to Damayantī''s svayaṃvara, met Nala and bound him by his promise to be their messenger to her.','v0350.mbh_nala','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_nala.04','hero.indian.nala','NARRATIVE_ACTION','hero.indian.damayanti',NULL,NULL,'Mahābhārata, Vana Parva, Sections LV–LVI say Nala, made invisible by the gods, delivered their suit to Damayantī, who answered that her heart was his and that she would choose him before the gods so that he would not break his word.','v0350.mbh_nala','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_nala.05','hero.indian.damayanti','NARRATIVE_ACTION','hero.indian.nala',NULL,NULL,'Mahābhārata, Vana Parva, Section LVII says that at the svayaṃvara the four gods took Nala''s form, and that when Damayantī prayed they showed the marks of gods — no sweat, unblinking eyes, unfaded garlands, feet not touching the ground — so that she chose the real Nala.','v0350.mbh_nala','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_nala.06','being.hindu.kali','NARRATIVE_ACTION','hero.indian.nala',NULL,NULL,'Mahābhārata, Vana Parva, Sections LVII–LVIII say the gods gave Nala boons and he lived happily with Damayantī, but Kali, angered that she had chosen a mortal, resolved to enter Nala and ruin him with Dvāpara''s help in the dice.','v0350.mbh_nala','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_nala.07','being.hindu.kali','NARRATIVE_ACTION','person.indian.pushkara',NULL,NULL,'Mahābhārata, Vana Parva, Sections LIX–LXI say Kali entered Nala after twelve years when he prayed without washing his feet, that Nala then lost everything at dice to Pushkara despite all pleading, and that Damayantī sent their children to Vidarbha before following him out of the city.','v0350.mbh_nala','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_nala.08','hero.indian.nala','NARRATIVE_ACTION','hero.indian.damayanti',NULL,NULL,'Mahābhārata, Vana Parva, Sections LXI–LXII say the dice, in the shape of golden birds, carried off Nala''s last garment, and that at midnight in a rest-house he cut away half of the sleeping Damayantī''s garment and, driven by Kali, abandoned her.','v0350.mbh_nala','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_nala.09','hero.indian.damayanti','NARRATIVE_ACTION',NULL,'survives the forest and finds refuge at the Chedi court','string','Mahābhārata, Vana Parva, Sections LXIII–LXV say the abandoned Damayantī was saved from a python by a hunter whom she cursed to death when he threatened her, survived a stampede that destroyed a caravan, and was taken in at the Chedi court.','v0350.mbh_nala','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_nala.10','creature.indian.karkotaka','NARRATIVE_ACTION','hero.indian.nala',NULL,NULL,'Mahābhārata, Vana Parva, Section LXVI says Nala carried the nāga Karkoṭaka out of a forest fire, that Karkoṭaka bit him at the tenth step and changed his form so that he would not be known, and sent him to King Ṛtuparṇa of Ayodhyā as the charioteer Bāhuka.','v0350.mbh_nala','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_nala.11','hero.indian.damayanti','NARRATIVE_ACTION','hero.indian.nala',NULL,NULL,'Mahābhārata, Vana Parva, Sections LXVII–LXX say the brahmin Sudeva found Damayantī at the Chedi court by her mole, and that the words she sent out after Nala drew a sighing answer from Ṛtuparṇa''s charioteer Bāhuka, reported by the brahmin Parṇāda.','v0350.mbh_nala','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_nala.12','person.indian.rituparna','NARRATIVE_ACTION','hero.indian.nala',NULL,NULL,'Mahābhārata, Vana Parva, Sections LXXI–LXXII say Ṛtuparṇa raced to Damayantī''s announced second svayaṃvara with Bāhuka driving, and at a Vibhītaka tree taught him the science of dice in exchange for horse-lore, whereupon Kali left Nala, vomiting Karkoṭaka''s venom.','v0350.mbh_nala','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_nala.13','hero.indian.damayanti','NARRATIVE_ACTION','hero.indian.nala',NULL,NULL,'Mahābhārata, Vana Parva, Sections LXXIII–LXXVI say Damayantī tested Bāhuka through her maid Keśinī, knew him by his cooking and his tears for their children, and that when the wind god attested her faithfulness Nala resumed his true form.','v0350.mbh_nala','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_nala.14','hero.indian.nala','NARRATIVE_ACTION','person.indian.pushkara',NULL,NULL,'Mahābhārata, Vana Parva, Sections LXXVII–LXXIX say Nala returned to Nishadha, won back his kingdom from Pushkara in a single throw with the science of dice, forgave his brother, and that Bṛhadaśva then taught the science of dice to Yudhiṣṭhira.','v0350.mbh_nala','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_savitri.01','person.indian.ashvapati','NARRATIVE_ACTION',NULL,'is visited by the goddess Sāvitrī after eighteen years of devotion','string','Mahābhārata, Vana Parva, Section CCXCI says that when Yudhiṣṭhira asked Mārkaṇḍeya about a woman as virtuous as Draupadī, the sage told of childless King Aśvapati of Madra, to whom the goddess Sāvitrī appeared from the sacrificial fire after eighteen years of vows and offerings.','v0350.mbh_savitri','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_savitri.02','hero.indian.savitri','NARRATIVE_ACTION','person.indian.ashvapati',NULL,NULL,'Mahābhārata, Vana Parva, Section CCXCI says the goddess, by Brahmā''s will, promised Aśvapati a radiant daughter instead of the sons he asked for, and that the child born to his queen was named Sāvitrī after her.','v0350.mbh_savitri','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_savitri.03','person.indian.ashvapati','NARRATIVE_ACTION','hero.indian.savitri',NULL,NULL,'Mahābhārata, Vana Parva, Section CCXCI says that because no one dared to seek the radiant Sāvitrī in marriage, her father sent her out with old ministers to choose a husband for herself.','v0350.mbh_savitri','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_savitri.04','hero.indian.savitri','NARRATIVE_ACTION','hero.indian.satyavan',NULL,NULL,'Mahābhārata, Vana Parva, Section CCXCII says Sāvitrī chose Satyavān, son of the blind, exiled King Dyumatsena, and that the sage Nārada praised Satyavān''s virtues but foretold that he would die a year from that day.','v0350.mbh_savitri','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_savitri.05','hero.indian.savitri','NARRATIVE_ACTION',NULL,'refuses to choose again though Satyavān is fated to die','string','Mahābhārata, Vana Parva, Section CCXCII says Sāvitrī refused to choose another husband, saying a daughter is given in marriage only once, and that Nārada advised Aśvapati to give her to Satyavān.','v0350.mbh_savitri','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_savitri.06','hero.indian.savitri','NARRATIVE_ACTION','hero.indian.satyavan',NULL,NULL,'Mahābhārata, Vana Parva, Section CCXCIII says Aśvapati gave Sāvitrī in marriage to Satyavān at Dyumatsena''s forest hermitage, and that she put aside her ornaments for bark garments and served her husband''s parents.','v0350.mbh_savitri','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_savitri.07','hero.indian.savitri','NARRATIVE_ACTION',NULL,'keeps a three-night vow before the foretold day','string','Mahābhārata, Vana Parva, Section CCXCIV says that with four days left before Satyavān''s foretold death Sāvitrī kept a three-night vow standing without food or drink, and on the fourth day accepted the elders'' blessing that she would never be widowed.','v0350.mbh_savitri','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_savitri.08','hero.indian.savitri','NARRATIVE_ACTION','hero.indian.satyavan',NULL,NULL,'Mahābhārata, Vana Parva, Section CCXCIV says that on the fated day Sāvitrī, with her husband''s parents'' leave, went with Satyavān into the forest, smiling at the sights he showed her while she watched him as one about to die.','v0350.mbh_savitri','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_savitri.09','deity.hindu.yama','NARRATIVE_ACTION','hero.indian.satyavan',NULL,NULL,'Mahābhārata, Vana Parva, Section CCXCV says that as Satyavān lay with his head in Sāvitrī''s lap, Yama, red-clad and crowned with a noose in his hand, came himself because of Satyavān''s virtue and drew out his thumb-sized soul.','v0350.mbh_savitri','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_savitri.10','hero.indian.savitri','NARRATIVE_ACTION','deity.hindu.yama',NULL,NULL,'Mahābhārata, Vana Parva, Section CCXCV says Sāvitrī followed Yama, invoking the friendship of seven steps and speaking of dharma, and that the pleased Yama granted her first boon, the restoration of her blind father-in-law''s sight and strength.','v0350.mbh_savitri','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_savitri.11','deity.hindu.yama','NARRATIVE_ACTION','hero.indian.satyavan',NULL,NULL,'Mahābhārata, Vana Parva, Section CCXCV says Yama granted Sāvitrī further boons — her father-in-law''s kingdom, a hundred sons for her father and a hundred sons by Satyavān — and, since the last could not be fulfilled without Satyavān, loosened his noose and restored her husband.','v0350.mbh_savitri','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_savitri.12','hero.indian.satyavan','NARRATIVE_ACTION','hero.indian.savitri',NULL,NULL,'Mahābhārata, Vana Parva, Section CCXCVI says Satyavān woke in Sāvitrī''s lap as from a long sleep, wept for his anxious parents, and that she supported him and carried his axe as they returned through the forest at night.','v0350.mbh_savitri','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_savitri.13','person.indian.dyumatsena','NARRATIVE_ACTION',NULL,'regains his sight and his kingdom through Sāvitrī''s boons','string','Mahābhārata, Vana Parva, Sections CCXCVI–CCXCVII say Dyumatsena regained his sight that day, Sāvitrī told the hermitage of Yama and the boons, and the next morning ministers of Śālva announced the usurper''s death and recalled Dyumatsena to his throne.','v0350.mbh_savitri','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_kurukshetra.01','deity.hindu.krishna','NARRATIVE_ACTION','hero.indian.duryodhana',NULL,NULL,'Mahābhārata, Udyoga Parva (Bhagavat-yana Parva) says Kṛṣṇa went to Hastināpura as the Pāṇḍavas'' envoy and asked for half the kingdom or even five villages, and that Duryodhana refused to yield even as much land as a needle''s point.','v0350.mbh_kurukshetra','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_kurukshetra.02','hero.indian.arjuna','NARRATIVE_ACTION','deity.hindu.krishna',NULL,NULL,'Mahābhārata, Bhishma Parva (Bhagavat-Gita Parva) says Arjuna, seeing his kin and teachers in the opposing army, laid down his bow, and that Kṛṣṇa, his charioteer, spoke to him between the armies in the discourse known as the Bhagavad Gītā, after which he took up his bow.','v0350.mbh_kurukshetra','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_kurukshetra.03','hero.indian.bhishma','NARRATIVE_ACTION','hero.indian.arjuna',NULL,NULL,'Mahābhārata, Bhishma Parva (Bhishma-vadha Parva) says that on the tenth day Bhīṣma, refusing to strike at Śikhaṇḍin, fell beneath Arjuna''s arrows onto a bed of arrows, where Arjuna gave him a pillow of arrows and water from the earth, and he chose to await the sun''s northern course before dying.','v0350.mbh_kurukshetra','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_kurukshetra.04','hero.indian.abhimanyu','NARRATIVE_ACTION','hero.indian.drona',NULL,NULL,'Mahābhārata, Drona Parva (Abhimanyu-vadha Parva) says the young Abhimanyu, knowing how to enter Droṇa''s circular array but not how to leave it, broke in while Jayadratha held back the other Pāṇḍavas, and was killed by several warriors together.','v0350.mbh_kurukshetra','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_kurukshetra.05','hero.indian.arjuna','NARRATIVE_ACTION',NULL,'vows to kill Jayadratha before sunset and fulfils the vow','string','Mahābhārata, Drona Parva (Pratijna and Jayadratha-vadha Parvas) says Arjuna vowed to kill Jayadratha before sunset or enter the fire, and that when Kṛṣṇa darkened the sun and Jayadratha showed himself, Arjuna struck off his head and sent it into his father''s lap.','v0350.mbh_kurukshetra','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_kurukshetra.06','hero.indian.karna','NARRATIVE_ACTION',NULL,'spends Indra''s dart on Ghaṭotkaca','string','Mahābhārata, Drona Parva (Ghatotkacha-vadha Parva) says that in the night battle Karṇa, begged by Duryodhana, spent the one-time dart from Indra that he had kept for Arjuna on Bhīma''s rākṣasa son Ghaṭotkaca, and that Kṛṣṇa rejoiced that Arjuna was saved.','v0350.mbh_kurukshetra','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_kurukshetra.07','hero.indian.yudhishthira','NARRATIVE_ACTION','hero.indian.drona',NULL,NULL,'Mahābhārata, Drona Parva (Drona-vadha Parva) says that after Bhīma killed an elephant named Aśvatthāman, Yudhiṣṭhira told Droṇa that Aśvatthāman was dead, adding ''the elephant'' under his breath; his chariot touched the ground, and Droṇa laid down his arms and was slain by Dhṛṣṭadyumna.','v0350.mbh_kurukshetra','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_kurukshetra.08','hero.indian.karna','NARRATIVE_ACTION','hero.indian.arjuna',NULL,NULL,'Mahābhārata, Karna Parva says that on the seventeenth day Karṇa''s chariot wheel sank into the earth through a brahmin''s curse, that Kṛṣṇa answered his appeal to dharma by recalling Draupadī and Abhimanyu, and that Arjuna struck off his head.','v0350.mbh_kurukshetra','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_kurukshetra.09','hero.indian.duryodhana','NARRATIVE_ACTION','hero.indian.yudhishthira',NULL,NULL,'Mahābhārata, Shalya Parva (Hrada-pravesa Parva) says that after Śalya and Śakuni were slain Duryodhana fled and hid beneath a lake, and that when Yudhiṣṭhira offered single combat with any of the five for the kingdom he rose to fight with the mace, and Bhīma met him.','v0350.mbh_kurukshetra','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_kurukshetra.10','hero.indian.bhima','NARRATIVE_ACTION','hero.indian.duryodhana',NULL,NULL,'Mahābhārata, Shalya Parva (Gada-yuddha Parva) says that, prompted by a sign from Arjuna recalling his vow, Bhīma broke Duryodhana''s thighs with his mace against the rules of the duel, angering Balarāma, while flowers fell from heaven on the fallen king.','v0350.mbh_kurukshetra','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_kurukshetra.11','hero.indian.ashvatthama','NARRATIVE_ACTION','hero.indian.draupadi',NULL,NULL,'Mahābhārata, Sauptika Parva says Aśvatthāman, inspired by an owl killing sleeping crows, raided the Pāṇḍava camp by night and killed Dhṛṣṭadyumna, Śikhaṇḍin and Draupadī''s five sons in the sleeping camp, and that the dying Duryodhana was content on hearing it.','v0350.mbh_kurukshetra','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.mbh_kurukshetra.12','deity.hindu.krishna','NARRATIVE_ACTION','hero.indian.ashvatthama',NULL,NULL,'Mahābhārata, Sauptika Parva (Aishika Parva) says that when Aśvatthāman, overtaken, loosed the Brahmaśiras weapon and turned it on the Pāṇḍavas'' unborn heirs, Kṛṣṇa cursed him to wander for three thousand years, and he gave up the jewel on his forehead.','v0350.mbh_kurukshetra','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Mahābhārata (Ganguli translation)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_zal.01','hero.persian.sam','NARRATIVE_ACTION','hero.persian.zal',NULL,NULL,'The Shahnameh, as retold by Zimmern (''Zal''), says Sām, ashamed that his newborn son had white hair and fearing he would be called a demon''s child, had the baby exposed on Mount Alborz.','v0350.shn_zal','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_zal.02','creature.persian.simorgh','NARRATIVE_ACTION','hero.persian.zal',NULL,NULL,'The Shahnameh, as retold by Zimmern (''Zal''), says the Simorgh carried the exposed baby to her nest on Alborz to feed her young but, moved to pity, raised him with them until he grew into a youth seen by passing caravans.','v0350.shn_zal','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_zal.03','hero.persian.sam','NARRATIVE_ACTION',NULL,'repents after two dreams and seeks his son on Mount Alborz','string','The Shahnameh, as retold by Zimmern (''Zal''), says Sām, rebuked in two dreams and by his priests for casting off his son, repented, went to Mount Alborz, and prayed to the Creator to be given him back.','v0350.shn_zal','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_zal.04','creature.persian.simorgh','NARRATIVE_ACTION','hero.persian.sam',NULL,NULL,'The Shahnameh, as retold by Zimmern (''Zal''), says the Simorgh returned Zāl to his father, naming him Dastān and giving him a feather to burn in danger, and that the king''s astrologers foretold his greatness.','v0350.shn_zal','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_zal.05','hero.persian.rudabeh','NARRATIVE_ACTION','hero.persian.zal',NULL,NULL,'The Shahnameh, as retold by Zimmern (''Zal and Rudabeh''), says Zāl and Rūdābeh, daughter of King Mehrāb of Kābul, a descendant of Zahhāk, fell in love through report, and that Rūdābeh''s maidens agreed to help her.','v0350.shn_zal','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_zal.06','hero.persian.rudabeh','NARRATIVE_ACTION','hero.persian.zal',NULL,NULL,'The Shahnameh, as retold by Zimmern (''Zal and Rudabeh''), says Rūdābeh let down her long hair from her tower for Zāl to climb, but he climbed by his lasso instead, and they vowed to marry no one else.','v0350.shn_zal','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_zal.07','person.persian.manuchehr','NARRATIVE_ACTION','hero.persian.sam',NULL,NULL,'The Shahnameh, as retold by Zimmern (''Zal and Rudabeh''), says Sām, after the astrologers foretold a mighty hero from the match, was willing, but King Manūchehr, fearing Zahhāk''s blood, ordered him to march against Mehrāb''s Kābul.','v0350.shn_zal','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_zal.08','person.persian.sindokht','NARRATIVE_ACTION','hero.persian.sam',NULL,NULL,'The Shahnameh, as retold by Zimmern (''Zal and Rudabeh''), says Queen Sindokht stopped Mehrāb from killing their daughter and went herself with gifts to the advancing Sām, who, moved by her wisdom, swore to spare Kābul and bring about the marriage.','v0350.shn_zal','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_zal.09','hero.persian.zal','NARRATIVE_ACTION','person.persian.manuchehr',NULL,NULL,'The Shahnameh, as retold by Zimmern (''Zal and Rudabeh''), says Zāl answered the riddles of Manūchehr''s wise men — the twelve cypresses as the months, the black and white horses as night and day, the mower in the garden as death — and won the king''s consent.','v0350.shn_zal','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_zal.10','hero.persian.zal','NARRATIVE_ACTION','hero.persian.rudabeh',NULL,NULL,'The Shahnameh, as retold by Zimmern (''Zal and Rudabeh''), says Zāl and Rūdābeh were married with great festivities in Kābul in Sām''s presence and returned to Zābulistān, which Sām gave into Zāl''s rule.','v0350.shn_zal','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_zal.11','creature.persian.simorgh','NARRATIVE_ACTION','hero.persian.rostam',NULL,NULL,'The Shahnameh, as retold by Zimmern (''Rustem''), says that when Rūdābeh could not give birth, Zāl burned the Simorgh''s feather and the Simorgh instructed that she be drugged and the child drawn from her side, and that she named the child Rostam from her cry of deliverance.','v0350.shn_zal','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_zal.12','hero.persian.rostam','NARRATIVE_ACTION','creature.persian.rakhsh',NULL,NULL,'The Shahnameh, as retold by Zimmern (''Rustem''), says the young Rostam killed a raging white elephant with one blow of Sām''s mace and lassoed the rose-dappled colt Rakhsh, whose price the herdsman said was the land of Iran.','v0350.shn_zal','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_seven.01','person.persian.kay_kavus','NARRATIVE_ACTION','place.persian.mazandaran',NULL,NULL,'The Shahnameh, as retold by Zimmern (''The March into Mazinderan''), says Kay Kāvus, enchanted by a demon disguised as a minstrel singing of Māzandarān, resolved to conquer it, and his alarmed champions sent for Zāl.','v0350.shn_seven','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_seven.02','demon.persian.white_div','NARRATIVE_ACTION','person.persian.kay_kavus',NULL,NULL,'The Shahnameh, as retold by Zimmern (''The March into Mazinderan''), says that when Kay Kāvus, scorning Zāl''s warning, ravaged Māzandarān, the White Demon brought darkness and a storm of stones and hail that blinded the shah and his army, who were taken captive.','v0350.shn_seven','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_seven.03','creature.persian.rakhsh','NARRATIVE_ACTION',NULL,'kills a lion while Rostam sleeps in the first stage','string','The Shahnameh, as retold by Zimmern (''The March into Mazinderan''), says Rostam chose the short, perilous road to Māzandarān, and that on the first night, as he slept, Rakhsh killed a lion that attacked them, for which Rostam scolded him.','v0350.shn_seven','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_seven.04','hero.persian.rostam','NARRATIVE_ACTION',NULL,'is led to water by a ram in the desert','string','The Shahnameh, as retold by Zimmern (''The March into Mazinderan''), says that in the second stage Rostam, fainting with thirst in the desert, prayed to God and was led by a ram to a spring.','v0350.shn_seven','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_seven.05','creature.persian.rakhsh','NARRATIVE_ACTION','hero.persian.rostam',NULL,NULL,'The Shahnameh, as retold by Zimmern (''The March into Mazinderan''), says that in the third stage Rakhsh three times woke Rostam to a dragon that hid itself by magic, and that when Rostam finally saw it Rakhsh bit the dragon and Rostam cut off its head.','v0350.shn_seven','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_seven.06','hero.persian.rostam','NARRATIVE_ACTION',NULL,'unmasks and kills a witch by naming God','string','The Shahnameh, as retold by Zimmern (''The March into Mazinderan''), says that in the fourth stage a witch disguised as a beautiful girl joined Rostam at a feast, and that when he named God she turned back into a hag and he killed her.','v0350.shn_seven','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_seven.07','person.persian.olad','NARRATIVE_ACTION','hero.persian.rostam',NULL,NULL,'The Shahnameh, as retold by Zimmern (''The March into Mazinderan''), says that in the fifth stage Rostam, after tearing off the ears of a field-keeper who struck him, defeated and lassoed the local lord Olād and made him his guide with the promise of Māzandarān''s throne.','v0350.shn_seven','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_seven.08','hero.persian.rostam','NARRATIVE_ACTION',NULL,'tears off the head of the demon Arzhang','string','The Shahnameh, as retold by Zimmern (''The March into Mazinderan''), says that in the sixth stage Rostam rode alone into the camp of the demon Arzhang, tore off his head and flung it among the demons, who fled in terror.','v0350.shn_seven','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_seven.09','hero.persian.rostam','NARRATIVE_ACTION','demon.persian.white_div',NULL,NULL,'The Shahnameh, as retold by Zimmern (''The March into Mazinderan''), says that in the seventh stage Rostam entered the White Demon''s cave at noon when the demons slept, woke the demon rather than strike him sleeping, and after a desperate fight killed him and tore out his liver.','v0350.shn_seven','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_seven.10','person.persian.kay_kavus','NARRATIVE_ACTION','hero.persian.rostam',NULL,NULL,'The Shahnameh, as retold by Zimmern (''The March into Mazinderan''), says the blood of the White Demon''s liver, dropped by Rostam into the eyes of Kay Kāvus and his champions, restored their sight.','v0350.shn_seven','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_seven.11','hero.persian.rostam','NARRATIVE_ACTION','person.persian.olad',NULL,NULL,'The Shahnameh, as retold by Zimmern (''The March into Mazinderan''), says that when the king of Māzandarān turned himself into a rock in battle, Rostam carried the rock to the Iranian camp and threatened it until the king came out, and that Olād was then made ruler of Māzandarān.','v0350.shn_seven','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_seven.12','person.persian.kay_kavus','NARRATIVE_ACTION',NULL,'tries to fly to heaven on an eagle-drawn throne and falls','string','The Shahnameh, as retold by Zimmern (''Kai Kaous Committeth More Follies''), says that, tempted by a demon to rule the sky, Kay Kāvus tried to fly on a throne drawn by hungry eagles straining after meat on spears, fell into a forest, and was found and rebuked by Rostam and the champions.','v0350.shn_seven','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_sohrab.01','hero.persian.rostam','NARRATIVE_ACTION','creature.persian.rakhsh',NULL,NULL,'The Shahnameh, as retold by Zimmern (''Rustem and Sohrab''), says Rakhsh was stolen by Turanian riders while Rostam slept after hunting on the border, and that Rostam tracked him to Samangān, whose king welcomed him as a guest.','v0350.shn_sohrab','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_sohrab.02','hero.persian.tahmineh','NARRATIVE_ACTION','hero.persian.rostam',NULL,NULL,'The Shahnameh, as retold by Zimmern (''Rustem and Sohrab''), says Tahmineh, princess of Samangān, came to Rostam''s chamber by night, told him she had long loved him and wished to bear his son, and that Rostam then asked the king for her hand and married her.','v0350.shn_sohrab','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_sohrab.03','hero.persian.rostam','NARRATIVE_ACTION','hero.persian.sohrab',NULL,NULL,'The Shahnameh, as retold by Zimmern (''Rustem and Sohrab''), says Rostam, leaving Samangān, gave Tahmineh an armlet to bind on their son''s arm if a son were born, and that she bore Sohrāb and bound it on him.','v0350.shn_sohrab','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_sohrab.04','hero.persian.sohrab','NARRATIVE_ACTION','hero.persian.rostam',NULL,NULL,'The Shahnameh, as retold by Zimmern (''Rustem and Sohrab''), says Sohrāb grew wondrously fast, learned from Tahmineh that Rostam was his father, and resolved to invade Iran, overthrow Kay Kāvus and set Rostam on the throne.','v0350.shn_sohrab','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_sohrab.05','person.persian.afrasiyab','NARRATIVE_ACTION','hero.persian.sohrab',NULL,NULL,'The Shahnameh, as retold by Zimmern (''Rustem and Sohrab''), says Afrāsiyāb sent the generals Hūmān and Bārmān with an army to support Sohrāb, secretly charging them to keep father and son from knowing each other so that one might kill the other.','v0350.shn_sohrab','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_sohrab.06','hero.persian.gordafarid','NARRATIVE_ACTION','hero.persian.sohrab',NULL,NULL,'The Shahnameh, as retold by Zimmern (''Rustem and Sohrab''), says the warrior maiden Gordāfarid rode out against Sohrāb from the White Castle, was revealed when he knocked off her helmet, and escaped him with a false promise before the castle''s people fled by a secret way.','v0350.shn_sohrab','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_sohrab.07','person.persian.kay_kavus','NARRATIVE_ACTION','hero.persian.rostam',NULL,NULL,'The Shahnameh, as retold by Zimmern (''Rustem and Sohrab''), says Kay Kāvus summoned Rostam against the young invader, raged at his delay and ordered him hanged, and that Rostam rode off in anger until Gūdarz persuaded him that he would be thought afraid.','v0350.shn_sohrab','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_sohrab.08','hero.persian.rostam','NARRATIVE_ACTION',NULL,'kills Zende-razm unknowing while spying in the Turanian camp','string','The Shahnameh, as retold by Zimmern (''Rustem and Sohrab''), says Rostam, spying in the Turanian camp, unknowingly killed Tahmineh''s brother Zende-razm, who was to point him out to Sohrāb, and that the captive Hajīr lied to Sohrāb that Rostam was not with the army.','v0350.shn_sohrab','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_sohrab.09','hero.persian.sohrab','NARRATIVE_ACTION','hero.persian.rostam',NULL,NULL,'The Shahnameh, as retold by Zimmern (''Rustem and Sohrab''), says that on the first day Sohrāb asked his opponent whether he was Rostam, son of Zāl, that Rostam denied it, and that they fought with spears, swords and maces till evening without a victor.','v0350.shn_sohrab','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_sohrab.10','hero.persian.rostam','NARRATIVE_ACTION','hero.persian.sohrab',NULL,NULL,'The Shahnameh, as retold by Zimmern (''Rustem and Sohrab''), says that on the second day Sohrāb threw Rostam and was about to kill him, but Rostam claimed an Iranian custom that a foe may be slain only at the second fall, and Sohrāb let him go.','v0350.shn_sohrab','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_sohrab.11','hero.persian.rostam','NARRATIVE_ACTION','hero.persian.sohrab',NULL,NULL,'The Shahnameh, as retold by Zimmern (''Rustem and Sohrab''), says Rostam prayed for the return of the strength he had once asked God to lessen, and on the third day threw Sohrāb and stabbed him, whereupon the dying Sohrāb said his father Rostam would avenge him.','v0350.shn_sohrab','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.shn_sohrab.12','hero.persian.rostam','NARRATIVE_ACTION','hero.persian.sohrab',NULL,NULL,'The Shahnameh, as retold by Zimmern (''Rustem and Sohrab''), says Rostam recognised his dying son by the armlet he had left with Tahmineh, that Kay Kāvus withheld the healing elixir, and that Sohrāb died, Rostam carried him home, and Tahmineh died of grief within a year.','v0350.shn_sohrab','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Shahnameh (Zimmern''s prose retelling)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.soushenji.01','deity.chinese.zhinu','NARRATIVE_ACTION','hero.chinese.dong_yong',NULL,NULL,'Soushen ji juan 1 says Dong Yong sold himself to bury his father, and that the woman who became his wife wove a hundred bolts of silk in ten days to repay his master, revealed herself as the Weaving Maiden sent by the Lord of Heaven for his filial piety, and rose into the sky.','v0350.soushenji','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Soushen ji (Gan Bao, received twenty-juan text)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.soushenji.02','hero.chinese.gan_jiang','NARRATIVE_ACTION','hero.chinese.chi_bi',NULL,NULL,'Soushen ji juan 11 says the swordsmith Gan Jiang, foreseeing that the king of Chu would kill him for taking three years, brought only the female sword and left word that the male sword lay behind a pine on a stone, which his son Chi Bi found behind the pine pillar of the hall.','v0350.soushenji','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Soushen ji (Gan Bao, received twenty-juan text)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.soushenji.03','hero.chinese.chi_bi','NARRATIVE_ACTION',NULL,'gives his head and sword to a stranger to avenge his father','string','Soushen ji juan 11 says Chi Bi gave his own head and sword to a stranger, who boiled the head before the king of Chu, cut off the king''s head into the cauldron and then his own, so that the three heads were buried together as the Tomb of the Three Kings.','v0350.soushenji','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Soushen ji (Gan Bao, received twenty-juan text)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.soushenji.04','text.chinese.soushenji','NARRATIVE_ACTION',NULL,'keeps a promise across a thousand li and attends his dead friend''s burial','string','Soushen ji juan 11 says Fan Juqing kept his two-year promise to visit Zhang Yuanbo, and that after Zhang''s death a dream summoned him to the burial, where the coffin would not move until he came and bade his friend farewell.','v0350.soushenji','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Soushen ji (Gan Bao, received twenty-juan text)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.soushenji.05','text.chinese.soushenji','NARRATIVE_ACTION',NULL,'tells of the wrongly executed filial widow of Donghai and the three years'' drought','string','Soushen ji juan 11 says a filial widow of Donghai was falsely condemned for her mother-in-law''s suicide, that three years of drought followed until a new governor sacrificed at her grave, and adds the elders'' tale that her blood flowed up the bamboo pole as she had sworn.','v0350.soushenji','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Soushen ji (Gan Bao, received twenty-juan text)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.soushenji.06','person.chinese.han_ping','NARRATIVE_ACTION',NULL,'dies with his wife rather than be parted, and their graves grow the Trees of Longing','string','Soushen ji juan 11 says that after King Kang of Song took Han Ping''s wife, both husband and wife took their own lives, and that from their separate graves grew catalpas whose roots and branches intertwined, with a pair of mandarin ducks in them, called the Trees of Longing.','v0350.soushenji','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Soushen ji (Gan Bao, received twenty-juan text)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.soushenji.07','deity.chinese.change','NARRATIVE_ACTION',NULL,'steals the elixir and becomes the toad in the moon','string','Soushen ji juan 14 says Heng''e stole the drug of deathlessness that Yi had obtained from the Queen Mother of the West, consulted the diviner Youhuang, who called the journey auspicious, and entrusted herself to the moon, becoming the toad.','v0350.soushenji','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Soushen ji (Gan Bao, received twenty-juan text)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.soushenji.08','text.chinese.soushenji','NARRATIVE_ACTION',NULL,'tells how a girl and a horse''s hide became the first silkworms','string','Soushen ji juan 14 tells that a girl promised in jest to marry the horse if it brought her father home, that her father shot the horse, and that its hide carried her off and both turned into silkworms in a tree thereafter called sang, the mulberry.','v0350.soushenji','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Soushen ji (Gan Bao, received twenty-juan text)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.soushenji.09','text.chinese.soushenji','NARRATIVE_ACTION',NULL,'tells of the feather-robed woman whose robe was hidden','string','Soushen ji juan 14 tells of a man of Xinyu who hid the feather robe of one of several bird-women, married her and had three daughters, until she found the robe under the grain stack, flew away, and later came back for her daughters.','v0350.soushenji','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Soushen ji (Gan Bao, received twenty-juan text)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.soushenji.10','hero.chinese.ziyu','NARRATIVE_ACTION',NULL,'dies of longing and meets her beloved as a ghost','string','Soushen ji juan 16 says Ziyu, daughter of King Fuchai of Wu, died of grief when her father refused Han Zhong, met him as a ghost at her tomb and gave him a pearl, and appeared to her father to clear him, vanishing like smoke when her mother embraced her.','v0350.soushenji','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Soushen ji (Gan Bao, received twenty-juan text)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.soushenji.11','person.chinese.song_dingbo','NARRATIVE_ACTION',NULL,'outwits a ghost and sells it as a sheep','string','Soushen ji juan 16 says Song Dingbo, meeting a ghost at night, pretended to be a new ghost, learned that ghosts fear human spittle, carried the ghost into the market of Wan where it turned into a sheep, and sold it for fifteen hundred cash after spitting on it.','v0350.soushenji','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Soushen ji (Gan Bao, received twenty-juan text)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.soushenji.12','hero.chinese.li_ji','NARRATIVE_ACTION',NULL,'kills the maiden-devouring serpent of Yongling','string','Soushen ji juan 19 says Li Ji, youngest of six daughters, volunteered as the sacrifice to the great serpent of Yongling that had devoured nine girls, and killed it with a sword, a snake-biting dog and honeyed rice cakes, after which the king of Yue made her his queen.','v0350.soushenji','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Soushen ji (Gan Bao, received twenty-juan text)',NULL,NULL,'2026-10-24T18:00:00Z'),
('claim.v0350.soushenji.13','text.chinese.soushenji','NARRATIVE_ACTION',NULL,'tells of the dog that died saving its master from fire','string','Soushen ji juan 20 says the dog Black Dragon saved its drunken master Li Xinchun from a grass fire by soaking itself in a stream and wetting the grass around him until it died of exhaustion, and that the governor had it buried in the Tomb of the Faithful Dog.','v0350.soushenji','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Soushen ji (Gan Bao, received twenty-juan text)',NULL,NULL,'2026-10-24T18:00:00Z');

